-- DE-1B immutable whole-same whole relation; verified whole relation only; no accounting or VAT consumption. PostgreSQL 17 and trusted application schema.
BEGIN;
SELECT finance_assert_document_definitions(pg_catalog.current_schema());
-- DE-1B verified whole relation only. No journal, payment or VAT consumption.
CREATE OR REPLACE FUNCTION finance_same_time(p_source text,p_raw jsonb,p_stored text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE raw_value text; stored_value text; digits text; projected text; sufficient boolean:=false; matches boolean; valid_projected boolean:=false; valid_stored boolean:=false;
BEGIN
 IF p_stored IS NOT NULL AND length(p_stored)<=80 AND p_stored ~ '^[0-9TZ +:.\-]+$' THEN stored_value:=p_stored;END IF;
 IF jsonb_typeof(p_raw)='string' AND length(p_raw#>>'{}')<=80 AND (p_raw#>>'{}') ~ '^[0-9TZ +:.\-]+$' THEN raw_value:=p_raw#>>'{}';digits:=regexp_replace(raw_value,'[^0-9]','','g');
  IF length(digits)>=14 THEN projected:=substr(digits,1,4)||'-'||substr(digits,5,2)||'-'||substr(digits,7,2)||' '||substr(digits,9,2)||':'||substr(digits,11,2)||':'||substr(digits,13,2);
  ELSIF length(digits)>=8 THEN projected:=substr(digits,1,4)||'-'||substr(digits,5,2)||'-'||substr(digits,7,2);END IF;
 END IF;
 IF projected IS NOT NULL AND stored_value IS NOT NULL THEN matches:=projected=stored_value;END IF;
 IF projected ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}$' THEN
  valid_projected:=vat_followup_date(left(projected,10)) AND substr(projected,12,2)::integer<24 AND substr(projected,15,2)::integer<60 AND substr(projected,18,2)::integer<60;
 END IF;
 IF stored_value ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}$' THEN
  valid_stored:=vat_followup_date(left(stored_value,10)) AND substr(stored_value,12,2)::integer<24 AND substr(stored_value,15,2)::integer<60 AND substr(stored_value,18,2)::integer<60;
 END IF;
 sufficient:=COALESCE((raw_value ~ '^[0-9]{14}$' OR raw_value ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}$') AND valid_projected AND valid_stored,false);
 RETURN jsonb_build_object('sourceId',p_source,'version','card-approval-time-evidence-v1','rawValue',raw_value,'projectedValue',projected,'storedValue',stored_value,
 'projectionMatches',matches,'evidenceSufficient',sufficient,'status',CASE WHEN NOT sufficient THEN 'unavailable' WHEN matches THEN 'matched' ELSE 'conflict' END);
END $$;
CREATE OR REPLACE FUNCTION finance_same_input(p jsonb,p_save boolean DEFAULT false) RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$
DECLARE d jsonb; r jsonb; k text; expected text[];
BEGIN
 expected:=ARRAY['draft','caseId','expectedVersion','expectedRevisionId'];IF p_save THEN expected:=expected||ARRAY['expectedPreviewHash','requestId'];END IF;
 IF jsonb_typeof(p)<>'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p) key) IS DISTINCT FROM (SELECT array_agg(x ORDER BY x) FROM unnest(expected) x)
  OR NOT vat_followup_money(p->'expectedVersion') OR (p->>'expectedVersion')::numeric>2147483646 THEN RETURN false;END IF;
 IF p->'expectedVersion'='0'::jsonb THEN IF p->'caseId'<>'null'::jsonb OR p->'expectedRevisionId'<>'null'::jsonb THEN RETURN false;END IF;
 ELSIF finance_supply_id(p->'caseId') IS DISTINCT FROM true OR finance_supply_id(p->'expectedRevisionId') IS DISTINCT FROM true THEN RETURN false;END IF;
 IF p_save AND (finance_supply_id(p->'requestId') IS DISTINCT FROM true OR COALESCE(p->>'expectedPreviewHash','') !~ '^[a-f0-9]{64}$') THEN RETURN false;END IF;
 d:=p->'draft';IF jsonb_typeof(d)<>'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(d) key) IS DISTINCT FROM ARRAY['evidence','left','reason','reviewRevisionId','right','subjectId']
  OR finance_supply_id(d->'subjectId') IS DISTINCT FROM true OR finance_supply_id(d->'reviewRevisionId') IS DISTINCT FROM true OR length(btrim(d->>'reason')) NOT BETWEEN 1 AND 2000 OR d->>'reason' IS NULL THEN RETURN false;END IF;
 FOR k IN SELECT unnest(ARRAY['left','right']) LOOP r:=d->k;
  IF jsonb_typeof(r)<>'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(r) key) IS DISTINCT FROM ARRAY['documentId','observationId','portionId']
   OR finance_supply_id(r->'documentId') IS DISTINCT FROM true OR finance_supply_id(r->'portionId') IS DISTINCT FROM true OR finance_supply_id(r->'observationId') IS DISTINCT FROM true THEN RETURN false;END IF;
 END LOOP;
 r:=d->'evidence';IF jsonb_typeof(r)<>'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(r) key) IS DISTINCT FROM ARRAY['documentId','evidenceHash','location']
  OR finance_supply_id(r->'documentId') IS DISTINCT FROM true OR COALESCE(r->>'evidenceHash','') !~ '^[a-f0-9]{64}$' OR length(btrim(r->>'location')) NOT BETWEEN 1 AND 2000 OR r->>'location' IS NULL THEN RETURN false;END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;
CREATE OR REPLACE FUNCTION finance_same_document(p_id text,p_subject text,p_hash text) RETURNS jsonb LANGUAGE plpgsql STABLE AS $$
DECLARE d vat_filing_documents%ROWTYPE;
BEGIN
 SELECT * INTO d FROM vat_filing_documents WHERE document_id=p_id;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF d.subject_id<>p_subject OR d.content_sha256 IS DISTINCT FROM p_hash THEN RETURN NULL;END IF;
 IF d.size_bytes IS DISTINCT FROM octet_length(d.content_bytes) OR d.content_sha256 IS DISTINCT FROM encode(sha256(d.content_bytes),'hex') THEN RAISE EXCEPTION 'Same relation document integrity failure' USING ERRCODE='55000';END IF;
 RETURN jsonb_build_object('documentId',d.document_id,'subjectId',d.subject_id,'evidenceHash',d.content_sha256,'sizeBytes',d.size_bytes);
END $$;
CREATE TABLE IF NOT EXISTS finance_same_cases (
 case_id text PRIMARY KEY,subject_id text NOT NULL,pair_key text NOT NULL,created_request_id text NOT NULL UNIQUE,actor_user_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(subject_id,pair_key)
);
CREATE TABLE IF NOT EXISTS finance_same_requests (
 request_id text PRIMARY KEY,action text NOT NULL CHECK(action IN('verify','withdraw')),actor_user_id text NOT NULL,
 payload_json jsonb NOT NULL,payload_hash text NOT NULL CHECK(payload_hash=finance_document_hash(payload_json)),result_json jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS finance_same_revisions (
 revision_id text PRIMARY KEY,case_id text NOT NULL REFERENCES finance_same_cases(case_id),version integer NOT NULL CHECK(version>0),
 previous_revision_id text UNIQUE REFERENCES finance_same_revisions(revision_id),schema_version text NOT NULL CHECK(schema_version='de1b-whole-revision-v1'),
 state text NOT NULL CHECK(state IN('verified_same','withdrawn')),input_json jsonb NOT NULL,preview_json jsonb NOT NULL,basis_json jsonb NOT NULL,
 proof_hash text NOT NULL CHECK(proof_hash=finance_document_hash(jsonb_build_object('input',input_json,'preview',preview_json,'basis',basis_json))),
 withdrawal_reason text,request_id text NOT NULL UNIQUE REFERENCES finance_same_requests(request_id) DEFERRABLE INITIALLY DEFERRED,
 actor_user_id text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),apply_xid xid8 NOT NULL DEFAULT pg_current_xact_id(),
 UNIQUE(case_id,version),CHECK((version=1)=(previous_revision_id IS NULL)),CHECK((state='withdrawn')=(withdrawal_reason IS NOT NULL)),CHECK(withdrawal_reason IS NULL OR length(btrim(withdrawal_reason)) BETWEEN 1 AND 2000)
);
CREATE OR REPLACE FUNCTION finance_same_merchant(p jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE AS $$
DECLARE e card_merchant_corrections%ROWTYPE; keys text[]:=ARRAY['card_txn_id','card_id','approval_type','approval_num','approved_at','amount_total','supply_amount','tax_amount','service_charge','store_corp_num','store_name','store_tax_type'];
 current_basis jsonb; ordered_text text; h text; issues jsonb:='[]'; effective text; evidence_hash text;
BEGIN
 SELECT * INTO e FROM card_merchant_corrections WHERE card_txn_id=p->>'card_txn_id' ORDER BY version DESC LIMIT 1;
 IF NOT FOUND THEN RETURN NULL;END IF;
 -- Existing A uses JSON.stringify on this fixed insertion-ordered string/null object.
 SELECT jsonb_object_agg(k,to_jsonb(p->>k)), '{'||string_agg(to_jsonb(k)::text||':'||COALESCE(to_jsonb(p->>k)::text,'null'),',' ORDER BY ord)||'}' INTO current_basis,ordered_text FROM unnest(keys) WITH ORDINALITY x(k,ord);
 h:=encode(sha256(convert_to(ordered_text,'UTF8')),'hex');
 IF e.original_source_hash IS DISTINCT FROM h THEN issues:=issues||jsonb_build_array('사업자번호 정정 후 수집 원천이 달라졌습니다. 정정 증빙을 다시 검토하세요.');END IF;
 SELECT '{'||string_agg(to_jsonb(k)::text||':'||COALESCE((e.original_basis->k)::text,'null'),',' ORDER BY ord)||'}' INTO ordered_text FROM unnest(keys) WITH ORDINALITY x(k,ord);
 IF encode(sha256(convert_to(ordered_text,'UTF8')),'hex') IS DISTINCT FROM e.original_source_hash THEN issues:=issues||jsonb_build_array('사업자번호 정정의 저장 원본 근거가 일치하지 않습니다.');END IF;
 effective:=CASE WHEN e.action='correct' THEN e.corp_num ELSE p->>'store_corp_num' END;
 evidence_hash:=vat_followup_hash(jsonb_build_array(e.event_id,e.version,e.action,e.corp_num,e.original_source_hash,e.reason,e.evidence,e.actor_user_id,e.reviewed_by,e.created_at));
 RETURN jsonb_build_object('eventId',e.event_id,'version',e.version,'action',e.action,'originalCorpNum',p->>'store_corp_num','effectiveCorpNum',effective,
  'status',CASE WHEN jsonb_array_length(issues)>0 THEN 'review_required' WHEN e.action='correct' THEN 'corrected' ELSE 'original' END,'originalSourceHash',e.original_source_hash,'currentSourceHash',h,'evidenceHash',evidence_hash,'issues',issues,'originalBasis',e.original_basis);
END $$;
CREATE OR REPLACE FUNCTION finance_same_card_source(p jsonb) RETURNS text LANGUAGE plpgsql STABLE AS $$
DECLARE m jsonb; fields jsonb;
BEGIN
 m:=finance_same_merchant(p);fields:=jsonb_build_array('card-tax-v1',p->>'card_txn_id',p->>'card_id',p->>'approval_type',p->>'approval_num',p->>'approved_at',p->>'amount_total',p->>'supply_amount',p->>'tax_amount',p->>'service_charge',CASE WHEN m IS NULL THEN p->>'store_corp_num' ELSE m->>'effectiveCorpNum' END,p->>'store_tax_type',p->>'category_key',p->>'excluded');
 IF m IS NOT NULL THEN fields:=fields||jsonb_build_array(jsonb_build_array('merchant-correction-v1',m->>'eventId',m->'version',m->>'evidenceHash',m->>'status',m->'issues'));END IF;
 RETURN vat_followup_hash(fields);
END
$$;
CREATE OR REPLACE FUNCTION finance_same_side(p_draft jsonb,p_ref jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE AS $$
DECLARE o finance_document_observations%ROWTYPE; candidate jsonb; issues jsonb:='[]'; times jsonb:='[]'; reversals jsonb:='[]'; merchant jsonb; reversal_merchant jsonb; x jsonb; c jsonb; cr jsonb; orig_review jsonb; rev_review jsonb; diag jsonb; company jsonb; source_hash text; original_hash text; n numeric; counterparty text;
BEGIN
 SELECT * INTO o FROM finance_document_observations WHERE observation_id=p_ref->>'observationId' AND document_id=p_ref->>'documentId' AND subject_id=p_draft->>'subjectId';
 IF NOT FOUND THEN RETURN jsonb_build_object('issues',finance_document_issue('observation_missing','정확한 문서 관측을 선택하세요.'),'summary',NULL,'times',times);END IF;
 BEGIN PERFORM finance_document_assert_request(o.request_id);EXCEPTION WHEN serialization_failure OR deadlock_detected THEN RAISE;WHEN OTHERS THEN RAISE EXCEPTION 'Stored document proof unavailable' USING ERRCODE='55000';END;
 IF NOT EXISTS(SELECT 1 FROM finance_document_portions WHERE document_id=o.document_id AND portion_id=p_ref->>'portionId' AND locator='whole')
  OR EXISTS(SELECT 1 FROM finance_document_observations WHERE document_id=o.document_id AND version>o.version) THEN issues:=issues||finance_document_issue('observation_stale','최신 문서 전체 관측을 선택하세요.');END IF;
 candidate:=finance_document_candidate(o.subject_id,p_draft->>'reviewRevisionId',o.source_kind,o.source_id);
 IF candidate->>'canRegister' IS DISTINCT FROM 'true' OR candidate->'_safeSnapshot' IS DISTINCT FROM o.safe_snapshot_json OR o.review_revision_id IS DISTINCT FROM p_draft->>'reviewRevisionId'
  OR candidate->>'documentId' IS DISTINCT FROM o.document_id OR candidate->>'portionId' IS DISTINCT FROM p_ref->>'portionId'
 THEN issues:=issues||finance_document_issue('source_observation_changed','원천·회사·기록판이 바뀌었습니다. 양쪽을 같은 최신 기록판으로 재관측하세요.');END IF;
 company:=candidate#>'{_safeSnapshot,subject}';
 x:=candidate#>'{_safeSnapshot,sourceSnapshots,0}';counterparty:=CASE WHEN x->>'kind'='card' THEN x->>'storeCorpNum' WHEN x->>'direction'='purchase' THEN x->>'supplier' ELSE x->>'recipient' END;
 IF counterparty IS NULL OR counterparty !~ '^[0-9]{10}$' THEN issues:=issues||finance_document_issue('same_counterparty_unavailable','정확한 거래처 번호를 확인하세요.');END IF;
 IF finance_same_document(substr(company->>'evidenceRef',14),o.subject_id,company->>'evidenceHash') IS NULL OR left(COALESCE(company->>'evidenceRef',''),13)<>'vat-document:' THEN issues:=issues||finance_document_issue('subject_evidence_unavailable','해당일 회사 기준의 보관 증빙을 확인하세요.');END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(COALESCE(candidate#>'{_safeSnapshot,sourceSnapshots}','[]')) LOOP
  IF x->>'kind'='card' THEN
   SELECT to_jsonb(t) INTO c FROM card_transactions t WHERE card_txn_id=x->>'id';
   merchant:=finance_same_merchant(c);
   IF merchant IS NOT NULL AND (merchant->>'status'='review_required' OR merchant->>'effectiveCorpNum' IS DISTINCT FROM c->>'store_corp_num') THEN issues:=issues||finance_document_issue('merchant_correction_scope','현재 가맹점 정정 근거가 원문 whole과 다르거나 재검토가 필요합니다. 이 첫 범위는 정정 번호를 반영한 관계를 지원하지 않습니다. 재관측만으로 해결되지 않습니다.');END IF;
   diag:=finance_same_time(x->>'id',c#>'{raw_json,ApprovalDT}',c->>'approved_at');times:=times||jsonb_build_array(diag);
   IF diag->>'status'<>'matched' THEN issues:=issues||finance_document_issue('card_time_'||(diag->>'status'),'카드 원문 승인일시의 투영과 근거를 확인하세요.');END IF;
   SELECT to_jsonb(r) INTO orig_review FROM card_tax_reviews r WHERE card_txn_id=c->>'card_txn_id';
   source_hash:=finance_same_card_source(c);original_hash:=vat_followup_hash(jsonb_build_array(source_hash,orig_review->>'source_hash',orig_review->'decision',orig_review->>'tax_date',orig_review->>'reason',orig_review->>'evidence_ref'));
   FOR cr IN SELECT to_jsonb(t) FROM card_transactions t LEFT JOIN card_tax_reviews r ON r.card_txn_id=t.card_txn_id
    WHERE COALESCE(t.excluded,0)=0 AND (r.original_card_txn_id=c->>'card_txn_id' OR btrim(t.approval_type) IN('취소','부분취소','환불') AND t.card_id=c->>'card_id' AND t.approval_num=c->>'approval_num') ORDER BY t.card_txn_id LOOP
    SELECT to_jsonb(r) INTO rev_review FROM card_tax_reviews r WHERE card_txn_id=cr->>'card_txn_id';
    reversal_merchant:=finance_same_merchant(cr);
    diag:=finance_same_time(cr->>'card_txn_id',cr#>'{raw_json,ApprovalDT}',cr->>'approved_at');times:=times||jsonb_build_array(diag);
    reversals:=reversals||jsonb_build_array(jsonb_build_object('sourceId',cr->>'card_txn_id','sourceHash',finance_document_hash(cr-ARRAY['raw_json']),'rawHash',finance_document_hash(cr->'raw_json'),'review',rev_review,'time',diag,'merchant',reversal_merchant));
    IF diag->>'status'<>'matched' OR COALESCE(btrim(cr->>'approval_type'),'') NOT IN('취소','부분취소','환불') OR rev_review->>'original_card_txn_id' IS DISTINCT FROM c->>'card_txn_id' OR cr->>'card_id' IS DISTINCT FROM c->>'card_id' OR cr->>'store_corp_num' IS DISTINCT FROM c->>'store_corp_num'
     OR rev_review->>'source_hash' IS DISTINCT FROM finance_same_card_source(cr) OR rev_review->>'original_source_hash' IS DISTINCT FROM original_hash
     OR orig_review->>'source_hash' IS DISTINCT FROM source_hash OR rev_review->'decision' IS DISTINCT FROM orig_review->'decision'
     OR orig_review->>'decision' NOT IN('0','1') OR length(btrim(COALESCE(orig_review->>'reason','')))=0 OR length(btrim(COALESCE(orig_review->>'evidence_ref','')))=0
     OR length(btrim(COALESCE(rev_review->>'reason','')))=0 OR length(btrim(COALESCE(rev_review->>'evidence_ref','')))=0
     OR COALESCE(rev_review->>'reversal_reason','') NOT IN('return','contract_cancellation','price_adjustment','original_correction') OR vat_followup_date(rev_review->>'tax_date') IS DISTINCT FROM true
     OR abs((cr->>'amount_total')::numeric)<>abs((cr->>'supply_amount')::numeric)+abs((cr->>'tax_amount')::numeric)+abs(COALESCE((cr->>'service_charge')::numeric,0))
     OR reversal_merchant IS NOT NULL AND (reversal_merchant->>'status'='review_required' OR reversal_merchant->>'effectiveCorpNum' IS DISTINCT FROM cr->>'store_corp_num')
    THEN issues:=issues||finance_document_issue('cancellation_unresolved','원승인·취소 관계와 현재 검토 지문을 확인하세요.');END IF;
   END LOOP;
   FOR x IN SELECT to_jsonb(v) FROM unnest(ARRAY['amount_total','supply_amount','tax_amount','service_charge']) v LOOP
    EXECUTE format('SELECT COALESCE(sum(abs(t.%I)),0) FROM card_transactions t JOIN card_tax_reviews r USING(card_txn_id) WHERE r.original_card_txn_id=$1 AND COALESCE(t.excluded,0)=0 AND btrim(t.approval_type) IN(''취소'',''부분취소'',''환불'')',x#>>'{}') INTO n USING c->>'card_txn_id';
    IF n>abs(COALESCE((c->>(x#>>'{}'))::numeric,0)) THEN issues:=issues||finance_document_issue('cancellation_exceeds_original','연결된 취소 성분 합계가 원승인을 넘습니다.');END IF;
   END LOOP;
  ELSE
   IF COALESCE(x->>'modifyCode','')<>'' OR x->>'originalInvoiceId' IS NOT NULL OR COALESCE(x->>'originalApprovalNumber','')<>'' OR COALESCE(x->>'originalNtsSendKey','')<>'' THEN issues:=issues||finance_document_issue('correction_lineage_unresolved','수정 문서는 정확 계보 검토가 필요합니다.');END IF;
  END IF;
 END LOOP;
 RETURN jsonb_build_object('issues',issues,'times',times,'summary',p_ref||finance_document_summary(o.preview_json->'observation'),'counterparty',counterparty,'candidateHash',candidate->>'previewHash','snapshot',candidate->'_safeSnapshot','reversals',reversals,'merchant',merchant);
END $$;
CREATE OR REPLACE FUNCTION finance_same_pair(p_draft jsonb) RETURNS text LANGUAGE sql IMMUTABLE AS $$
 SELECT finance_document_hash(to_jsonb(ARRAY[least(p_draft#>>'{left,portionId}',p_draft#>>'{right,portionId}'),greatest(p_draft#>>'{left,portionId}',p_draft#>>'{right,portionId}')]))
$$;
CREATE OR REPLACE FUNCTION finance_same_c_target(p_id text,p_subject text) RETURNS jsonb LANGUAGE plpgsql STABLE AS $$
DECLARE c vat_followup_review_consumptions%ROWTYPE; a vat_followup_legacy_archives%ROWTYPE; rr jsonb; form jsonb; pairs jsonb; h text; subject text;
BEGIN
 SELECT * INTO STRICT c FROM vat_followup_review_consumptions WHERE consumption_id=p_id;
 IF (c.basis_confirmation_id IS NULL)=(c.legacy_archive_id IS NULL) THEN RAISE EXCEPTION 'C target identity invalid';END IF;
 IF c.basis_confirmation_id IS NOT NULL THEN
  h:=vat_post_confirmed_return_hash(c.basis_confirmation_id);
  SELECT b.subject_id,r.form_json INTO STRICT subject,form FROM vat_filing_return_confirmations x JOIN vat_filing_return_revisions r ON r.return_id=x.return_id JOIN vat_filing_basis_snapshots b ON b.snapshot_id=r.basis_snapshot_id WHERE x.confirmation_id=c.basis_confirmation_id;
  IF subject IS DISTINCT FROM p_subject OR form#>>'{followupConsumption,application,subjectId}' IS DISTINCT FROM p_subject OR h IS DISTINCT FROM c.calculation_hash THEN RAISE EXCEPTION 'C confirmation subject/hash invalid';END IF;
 ELSE
  SELECT * INTO STRICT a FROM vat_followup_legacy_archives WHERE archive_id=c.legacy_archive_id;
  SELECT to_jsonb(r) INTO STRICT rr FROM vat_returns r WHERE r.return_id=a.return_id;
  form:=vat_followup_validate_form_v2(a.form_json,'legacy',NULL);
  SELECT COALESCE(jsonb_agg(x.payload_json ORDER BY x.payload_json->>'revisionId' COLLATE "C",x.pair_line_no),'[]') INTO pairs FROM vat_followup_review_consumptions x WHERE x.legacy_archive_id=a.archive_id;
  IF a.schema_version<>'vat-return-legacy-v2' OR a.row_json IS DISTINCT FROM rr OR a.row_json->'form_json' IS DISTINCT FROM a.form_json OR rr->>'status'<>'confirmed' OR rr->>'period_kind'<>'final'
   OR rr->>'return_id' IS DISTINCT FROM a.return_id OR rr->>'confirmed_by' IS DISTINCT FROM a.created_by OR form#>>'{application,subjectId}' IS DISTINCT FROM p_subject
   OR a.calculation_hash IS DISTINCT FROM form->>'calculationHash' OR c.calculation_hash IS DISTINCT FROM a.calculation_hash OR form->'pairs' IS DISTINCT FROM pairs
   OR rr->'period_year' IS DISTINCT FROM form#>'{application,year}' OR rr->'period_term' IS DISTINCT FROM form#>'{application,term}' OR rr->>'date_from' IS DISTINCT FROM form#>>'{application,dateFrom}' OR rr->>'date_to' IS DISTINCT FROM form#>>'{application,dateTo}' OR a.form_json->'blockingIssues' IS DISTINCT FROM '[]'::jsonb
   OR EXISTS(SELECT 1 FROM vat_followup_review_consumptions x LEFT JOIN vat_followup_review_revisions v USING(revision_id) LEFT JOIN vat_followup_review_roots r USING(review_id)
     WHERE x.legacy_archive_id=a.archive_id AND (x.basis_confirmation_id IS NOT NULL OR x.created_by IS DISTINCT FROM a.created_by OR x.calculation_hash IS DISTINCT FROM a.calculation_hash OR x.payload_json->>'revisionId' IS DISTINCT FROM x.revision_id OR x.payload_json->'pairLineNo' IS DISTINCT FROM to_jsonb(x.pair_line_no) OR v.schema_version IS DISTINCT FROM 'vat-followup-review-v1' OR v.state IS DISTINCT FROM 'verified' OR v.payload_hash IS DISTINCT FROM vat_followup_hash(v.payload_json) OR v.payload_json#>ARRAY['pairs',x.pair_line_no::text] IS DISTINCT FROM x.payload_json->'pair' OR r.subject_id IS DISTINCT FROM p_subject)) THEN RAISE EXCEPTION 'C legacy confirmation integrity invalid';END IF;
  h:=a.calculation_hash;
 END IF;
 RETURN jsonb_build_object('consumptionId',c.consumption_id,'revisionId',c.revision_id,'pairLineNo',c.pair_line_no,'basisConfirmationId',c.basis_confirmation_id,'legacyArchiveId',c.legacy_archive_id,'calculationHash',h,'formHash',finance_document_hash(form));
EXCEPTION WHEN serialization_failure OR deadlock_detected THEN RAISE;WHEN OTHERS THEN RAISE EXCEPTION 'C target stored evidence unavailable' USING ERRCODE='55000';
END $$;
CREATE OR REPLACE FUNCTION finance_same_candidate(p_input jsonb,p_ignore_case text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE AS $$
DECLARE d jsonb; l jsonb; r jsonb; issues jsonb:='[]'; basis jsonb; result jsonb; last_row finance_same_revisions%ROWTYPE; root_row finance_same_cases%ROWTYPE;
 connected text[]; connected_docs text[]; e record; f jsonb; g jsonb; c_refs jsonb:='[]'; graph jsonb:='[]'; distinct_links jsonb:='[]'; proof jsonb; refdoc jsonb;
BEGIN
 IF finance_same_input(p_input) IS DISTINCT FROM true THEN RAISE EXCEPTION 'Invalid same relation input' USING ERRCODE='22023';END IF;
 d:=p_input->'draft';l:=finance_same_side(d,d->'left');r:=finance_same_side(d,d->'right');issues:=(l->'issues')||(r->'issues');
 IF d#>>'{left,portionId}'=d#>>'{right,portionId}' OR d#>>'{left,documentId}'=d#>>'{right,documentId}' THEN issues:=issues||finance_document_issue('same_identity_self','별칭이 합쳐진 같은 문서 자체를 중복 확인할 수 없습니다.');END IF;
 IF l->'summary' IS NULL OR r->'summary' IS NULL OR l#>'{summary,supply}' IS DISTINCT FROM r#>'{summary,supply}' OR l#>'{summary,tax}' IS DISTINCT FROM r#>'{summary,tax}' OR l#>'{summary,total}' IS DISTINCT FROM r#>'{summary,total}' OR l#>'{summary,direction}' IS DISTINCT FROM r#>'{summary,direction}' THEN issues:=issues||finance_document_issue('whole_amount_mismatch','문서 전체의 방향·공급가액·세액·합계가 일치해야 합니다. 부분은 아직 지원하지 않습니다.');END IF;
 IF l->>'counterparty' IS DISTINCT FROM r->>'counterparty' THEN issues:=issues||finance_document_issue('same_counterparty_mismatch','두 문서의 거래처가 다릅니다.');END IF;
 refdoc:=finance_same_document(d#>>'{evidence,documentId}',d->>'subjectId',d#>>'{evidence,evidenceHash}');IF refdoc IS NULL THEN issues:=issues||finance_document_issue('evidence_unavailable','같은 회사의 보관 증빙과 해시를 확인하세요.');END IF;
 IF p_input->>'caseId' IS NOT NULL THEN
  SELECT * INTO root_row FROM finance_same_cases WHERE case_id=p_input->>'caseId';SELECT * INTO last_row FROM finance_same_revisions WHERE case_id=p_input->>'caseId' ORDER BY version DESC LIMIT 1;
  IF root_row.subject_id IS DISTINCT FROM d->>'subjectId' OR root_row.pair_key IS DISTINCT FROM finance_same_pair(d) OR last_row.version IS DISTINCT FROM (p_input->>'expectedVersion')::integer OR last_row.revision_id IS DISTINCT FROM p_input->>'expectedRevisionId' THEN issues:=issues||finance_document_issue('same_revision_stale','현재 관계의 최신 판을 다시 선택하세요.');END IF;
 ELSIF EXISTS(SELECT 1 FROM finance_same_cases WHERE subject_id=d->>'subjectId' AND pair_key=finance_same_pair(d) AND case_id IS DISTINCT FROM p_ignore_case) THEN issues:=issues||finance_document_issue('same_case_exists','이미 기록된 관계의 최신 판으로 검토하세요.');END IF;
 WITH RECURSIVE edges AS (SELECT v.input_json#>>'{draft,left,portionId}' a,v.input_json#>>'{draft,right,portionId}' b FROM finance_same_revisions v JOIN finance_same_cases c USING(case_id)
  WHERE c.subject_id=d->>'subjectId' AND v.state='verified_same' AND c.case_id IS DISTINCT FROM COALESCE(p_input->>'caseId',p_ignore_case) AND NOT EXISTS(SELECT 1 FROM finance_same_revisions n WHERE n.case_id=v.case_id AND n.version>v.version)),
 walk(p) AS (SELECT unnest(ARRAY[d#>>'{left,portionId}',d#>>'{right,portionId}']) UNION SELECT CASE WHEN edge_row.a=w.p THEN edge_row.b ELSE edge_row.a END FROM walk w JOIN edges edge_row ON edge_row.a=w.p OR edge_row.b=w.p)
 SELECT array_agg(p ORDER BY p) INTO connected FROM walk;
 SELECT array_agg(DISTINCT document_id ORDER BY document_id) INTO connected_docs FROM finance_document_portions WHERE portion_id=ANY(connected);
 FOR e IN SELECT v.* FROM finance_same_revisions v JOIN finance_same_cases c USING(case_id) WHERE c.subject_id=d->>'subjectId' AND v.state='verified_same' AND c.case_id IS DISTINCT FROM COALESCE(p_input->>'caseId',p_ignore_case)
  AND NOT EXISTS(SELECT 1 FROM finance_same_revisions n WHERE n.case_id=v.case_id AND n.version>v.version) AND (v.input_json#>>'{draft,left,portionId}'=ANY(connected) OR v.input_json#>>'{draft,right,portionId}'=ANY(connected)) ORDER BY v.revision_id LOOP
  f:=finance_same_side(e.input_json->'draft',e.input_json#>'{draft,left}');g:=finance_same_side(e.input_json->'draft',e.input_json#>'{draft,right}');
  IF f->'issues'<>'[]'::jsonb OR g->'issues'<>'[]'::jsonb OR f IS DISTINCT FROM e.basis_json->'left' OR g IS DISTINCT FROM e.basis_json->'right' THEN issues:=issues||finance_document_issue('same_graph_stale','전이에 사용하는 기존 관계의 원천을 먼저 재검토하세요.');END IF;
  graph:=graph||jsonb_build_array(jsonb_build_object('revisionId',e.revision_id,'proofHash',e.proof_hash));
 END LOOP;
 FOR e IN SELECT t.* FROM transaction_links t WHERE t.relation='distinct' AND t.state='active'
  AND EXISTS(SELECT 1 FROM finance_document_sources s WHERE s.document_id=ANY(connected_docs) AND s.source_kind=t.left_kind AND s.source_id=t.left_id)
  AND EXISTS(SELECT 1 FROM finance_document_sources s JOIN finance_document_registry d0 USING(document_id) WHERE s.document_id=ANY(connected_docs) AND (s.source_kind=t.right_kind AND s.source_id=t.right_id OR t.canonical_invoice_key='invoice:'||(d0.descriptor_json->>1))) ORDER BY t.link_id LOOP
  -- A stale active declaration is not erased or treated as proof of sameness.
  distinct_links:=distinct_links||jsonb_build_array(jsonb_build_object('linkId',e.link_id,'snapshotHash',finance_document_hash(to_jsonb(e)),'leftHash',e.left_hash,'rightHash',e.right_hash));
  issues:=issues||finance_document_issue('distinct_relation_unresolved','같은 연결 성분에 별개 공급 선언이 있습니다. 정확 원천과 선언의 현재 근거를 먼저 해결하세요.');
 END LOOP;
 FOR e IN SELECT p.*,v.state,v.payload_hash,v.payload_json,v.review_id,root.subject_id,c.consumption_id,c.payload_json AS consumption,c.basis_confirmation_id,c.legacy_archive_id,c.calculation_hash FROM vat_followup_review_pairs p
  JOIN vat_followup_review_revisions v USING(revision_id) JOIN vat_followup_review_roots root USING(review_id)
  LEFT JOIN vat_followup_review_consumptions c ON c.revision_id=p.revision_id AND c.pair_line_no=p.line_no
  WHERE root.subject_id=d->>'subjectId' AND (c.consumption_id IS NOT NULL OR v.state='verified' AND NOT EXISTS(SELECT 1 FROM vat_followup_review_revisions n WHERE n.review_id=v.review_id AND n.version>v.version))
   AND (EXISTS(SELECT 1 FROM finance_document_sources s WHERE s.document_id=ANY(connected_docs) AND s.source_kind='card' AND s.source_id=p.card_source_id) OR EXISTS(SELECT 1 FROM finance_document_sources s WHERE s.document_id=ANY(connected_docs) AND s.source_kind='hometax' AND s.source_id=p.invoice_source_id)) ORDER BY p.revision_id,p.line_no LOOP
  IF e.state<>'verified' OR e.payload_hash IS DISTINCT FROM vat_followup_hash(e.payload_json) OR e.payload_json#>ARRAY['pairs',e.line_no::text] IS DISTINCT FROM e.pair_json THEN RAISE EXCEPTION 'C pair archive mismatch' USING ERRCODE='55000';END IF;
  IF e.pair_json->'databaseProof' IS DISTINCT FROM vat_followup_database_proof(e.card_source_id,e.invoice_source_id,e.legacy_return_id,e.past_basis_snapshot_id,e.past_fact_revision_id) THEN issues:=issues||finance_document_issue('c_source_stale','관련 C 정확 쌍의 현재 원천 근거를 재검토하세요.');END IF;
  IF e.consumption_id IS NOT NULL THEN
   proof:=finance_same_c_target(e.consumption_id,d->>'subjectId');
  ELSE proof:=NULL;END IF;
  c_refs:=c_refs||jsonb_build_array(jsonb_build_object('revisionId',e.revision_id,'pairLineNo',e.line_no,'pairHash',finance_document_hash(e.pair_json),'consumptionId',e.consumption_id,'targetProof',proof,'claimedSupply',NULL,'claimedTax',e.pair_json#>'{past,claim,claimedTax}'));
  IF EXISTS(SELECT 1 FROM finance_document_sources s WHERE s.document_id=ANY(connected_docs) AND s.source_kind='card' AND s.source_id=e.card_source_id) AND EXISTS(SELECT 1 FROM finance_document_sources s WHERE s.document_id=ANY(connected_docs) AND s.source_kind='hometax' AND s.source_id=e.invoice_source_id) THEN issues:=issues||finance_document_issue('c_distinct_conflict','정확한 C 별개 공급 쌍과 같은 공급 관계가 모순됩니다.');END IF;
 END LOOP;
 basis:=jsonb_build_object('version','de1b-whole-basis-v1','left',l,'right',r,'evidence',refdoc,'graph',graph,'distinctLinks',distinct_links,'cReferences',c_refs);
 result:=jsonb_build_object('schemaVersion','de1b-whole-preview-v1','draft',d,'canVerify',jsonb_array_length(issues)=0,'issues',issues,'left',l->'summary','right',r->'summary','timeDiagnostics',(l->'times')||(r->'times'),'financialUseSupported',false);
 RETURN result||jsonb_build_object('previewHash',finance_document_hash(jsonb_build_object('input',p_input,'result',result,'basis',basis)),'_basis',basis);
END $$;
CREATE OR REPLACE FUNCTION finance_same_preview(p_input jsonb) RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT finance_same_candidate(p_input)-'_basis' $$;
CREATE OR REPLACE FUNCTION finance_same_lock() RETURNS void LANGUAGE plpgsql AS $$
BEGIN
 PERFORM finance_document_write_lock();
 LOCK TABLE finance_document_registry,finance_document_sources,finance_document_portions,finance_document_observations,finance_document_requests,
 vat_filing_documents,card_tax_reviews,card_merchant_corrections,vat_followup_review_roots,vat_followup_review_revisions,vat_followup_review_pairs,vat_followup_review_consumptions,
 vat_filing_return_confirmations,vat_filing_return_revisions,vat_filing_basis_snapshots,vat_filing_fact_revisions,vat_filing_basis_consumptions,
 vat_followup_legacy_archives,vat_returns,transaction_links,transaction_invoice_recognitions IN SHARE MODE;
END $$;
CREATE OR REPLACE FUNCTION finance_same_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Same relation history is immutable' USING ERRCODE='23514';END $$;
CREATE OR REPLACE FUNCTION finance_same_insert() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE prev finance_same_revisions%ROWTYPE; root finance_same_cases%ROWTYPE; p jsonb;
BEGIN
 PERFORM finance_same_lock();PERFORM finance_assert_same_definitions(current_schema());
 IF TG_TABLE_NAME='finance_same_revisions' THEN
  SELECT * INTO root FROM finance_same_cases WHERE case_id=NEW.case_id;SELECT * INTO prev FROM finance_same_revisions WHERE case_id=NEW.case_id ORDER BY version DESC LIMIT 1;
  IF NEW.apply_xid IS DISTINCT FROM pg_current_xact_id() OR NEW.version<>COALESCE(prev.version,0)+1 OR NEW.previous_revision_id IS DISTINCT FROM prev.revision_id OR finance_same_input(NEW.input_json) IS DISTINCT FROM true OR root.subject_id IS DISTINCT FROM NEW.input_json#>>'{draft,subjectId}' OR root.pair_key IS DISTINCT FROM finance_same_pair(NEW.input_json->'draft') THEN RAISE EXCEPTION 'Same relation root/version mismatch' USING ERRCODE='23514';END IF;
  IF NEW.state='verified_same' THEN
   p:=finance_same_candidate(NEW.input_json,NEW.case_id);
   IF p->>'canVerify'<>'true' OR NEW.preview_json IS DISTINCT FROM p-'_basis' OR NEW.basis_json IS DISTINCT FROM p->'_basis' THEN RAISE EXCEPTION 'Same relation current proof mismatch' USING ERRCODE='23514';END IF;
  ELSE
   IF prev.state IS DISTINCT FROM 'verified_same' OR NEW.input_json IS DISTINCT FROM prev.input_json OR NEW.preview_json IS DISTINCT FROM prev.preview_json OR NEW.basis_json IS DISTINCT FROM prev.basis_json THEN RAISE EXCEPTION 'Invalid same relation withdrawal' USING ERRCODE='23514';END IF;
  END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION finance_same_assert_request(p_request text) RETURNS void LANGUAGE plpgsql AS $$
DECLARE q finance_same_requests%ROWTYPE; v finance_same_revisions%ROWTYPE; c finance_same_cases%ROWTYPE; prev finance_same_revisions%ROWTYPE; expected jsonb; current_basis jsonb; side text; obs finance_document_observations%ROWTYPE;
BEGIN
 SELECT * INTO q FROM finance_same_requests WHERE request_id=p_request;SELECT * INTO v FROM finance_same_revisions WHERE request_id=p_request;SELECT * INTO c FROM finance_same_cases WHERE case_id=v.case_id;SELECT * INTO prev FROM finance_same_revisions WHERE revision_id=v.previous_revision_id;
 IF q.request_id IS NULL OR v.revision_id IS NULL OR c.case_id IS NULL OR q.actor_user_id IS DISTINCT FROM v.actor_user_id OR q.payload_hash IS DISTINCT FROM finance_document_hash(q.payload_json)
  OR finance_supply_id(to_jsonb(q.request_id)) IS DISTINCT FROM true OR finance_supply_id(to_jsonb(q.actor_user_id)) IS DISTINCT FROM true OR finance_same_input(v.input_json) IS DISTINCT FROM true
  OR c.subject_id IS DISTINCT FROM v.input_json#>>'{draft,subjectId}' OR c.pair_key IS DISTINCT FROM finance_same_pair(v.input_json->'draft') OR v.preview_json->'draft' IS DISTINCT FROM v.input_json->'draft'
  OR v.proof_hash IS DISTINCT FROM finance_document_hash(jsonb_build_object('input',v.input_json,'preview',v.preview_json,'basis',v.basis_json))
  OR v.preview_json->>'schemaVersion' IS DISTINCT FROM 'de1b-whole-preview-v1' OR v.preview_json->'financialUseSupported' IS DISTINCT FROM 'false'::jsonb OR v.preview_json->'canVerify' IS DISTINCT FROM 'true'::jsonb OR v.preview_json->'issues' IS DISTINCT FROM '[]'::jsonb
  OR v.preview_json->>'previewHash' IS DISTINCT FROM finance_document_hash(jsonb_build_object('input',v.input_json,'result',v.preview_json-'previewHash','basis',v.basis_json))
  OR (v.version=1 AND (c.created_request_id<>q.request_id OR c.actor_user_id<>q.actor_user_id)) OR (v.version>1 AND (prev.case_id IS DISTINCT FROM v.case_id OR prev.version IS DISTINCT FROM v.version-1))
 THEN RAISE EXCEPTION 'Same relation archive agreement failed' USING ERRCODE='23514';END IF;
 FOR side IN SELECT unnest(ARRAY['left','right']) LOOP
  SELECT * INTO obs FROM finance_document_observations WHERE observation_id=v.input_json#>>ARRAY['draft',side,'observationId'];
  IF obs.observation_id IS NULL OR obs.document_id IS DISTINCT FROM v.input_json#>>ARRAY['draft',side,'documentId'] OR obs.subject_id IS DISTINCT FROM c.subject_id OR obs.safe_snapshot_json IS DISTINCT FROM v.basis_json#>ARRAY[side,'snapshot']
   OR NOT EXISTS(SELECT 1 FROM finance_document_portions WHERE portion_id=v.input_json#>>ARRAY['draft',side,'portionId'] AND document_id=obs.document_id AND locator='whole') THEN RAISE EXCEPTION 'Same relation stored observation reference mismatch' USING ERRCODE='23514';END IF;
  PERFORM finance_document_assert_request(obs.request_id);
 END LOOP;
 expected:=jsonb_build_object('caseId',v.case_id,'revisionId',v.revision_id,'version',v.version,'state',v.state,'replayed',false,'financialUseSupported',false);
 IF q.result_json IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Same relation request result mismatch' USING ERRCODE='23514';END IF;
 IF v.state='verified_same' THEN
  IF q.action<>'verify' OR q.payload_json IS DISTINCT FROM v.input_json||jsonb_build_object('expectedPreviewHash',v.preview_json->>'previewHash','requestId',q.request_id) THEN RAISE EXCEPTION 'Same relation verify request mismatch' USING ERRCODE='23514';END IF;
 ELSE
  IF q.action<>'withdraw' OR prev.state IS DISTINCT FROM 'verified_same' OR v.input_json IS DISTINCT FROM prev.input_json OR v.preview_json IS DISTINCT FROM prev.preview_json OR v.basis_json IS DISTINCT FROM prev.basis_json
   OR q.payload_json IS DISTINCT FROM jsonb_build_object('subjectId',c.subject_id,'caseId',c.case_id,'expectedVersion',prev.version,'expectedRevisionId',prev.revision_id,'reason',v.withdrawal_reason,'requestId',q.request_id) THEN RAISE EXCEPTION 'Same relation withdrawal request mismatch' USING ERRCODE='23514';END IF;
 END IF;
 IF v.apply_xid=pg_current_xact_id_if_assigned() AND v.state='verified_same' THEN
  current_basis:=finance_same_candidate(v.input_json,v.case_id)->'_basis';
  IF current_basis IS DISTINCT FROM v.basis_json THEN RAISE EXCEPTION 'Same relation source changed before commit' USING ERRCODE='23514';END IF;
 END IF;
END $$;
CREATE OR REPLACE FUNCTION finance_same_agreement() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE req text;
BEGIN
 IF TG_TABLE_NAME='finance_same_cases' THEN
  req:=NEW.created_request_id;
  IF NOT EXISTS(SELECT 1 FROM finance_same_revisions v WHERE v.case_id=NEW.case_id AND v.version=1 AND v.request_id=NEW.created_request_id) THEN RAISE EXCEPTION 'Orphan same relation root' USING ERRCODE='23514';END IF;
 ELSE req:=NEW.request_id;END IF;
 PERFORM finance_same_assert_request(req);RETURN NULL;
END $$;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['finance_same_cases','finance_same_revisions','finance_same_requests'] LOOP
 EXECUTE format('DROP TRIGGER IF EXISTS finance_same_insert ON %I',t);EXECUTE format('CREATE TRIGGER finance_same_insert BEFORE INSERT ON %I FOR EACH ROW EXECUTE FUNCTION finance_same_insert()',t);
 EXECUTE format('DROP TRIGGER IF EXISTS finance_same_immutable ON %I',t);EXECUTE format('CREATE TRIGGER finance_same_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION finance_same_immutable()',t);
 EXECUTE format('DROP TRIGGER IF EXISTS finance_same_no_truncate ON %I',t);EXECUTE format('CREATE TRIGGER finance_same_no_truncate BEFORE TRUNCATE ON %I FOR EACH STATEMENT EXECUTE FUNCTION finance_same_immutable()',t);
 EXECUTE format('DROP TRIGGER IF EXISTS finance_same_agreement ON %I',t);EXECUTE format('CREATE CONSTRAINT TRIGGER finance_same_agreement AFTER INSERT ON %I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION finance_same_agreement()',t);
 END LOOP;END $$;
CREATE OR REPLACE FUNCTION finance_same_write(p_action text,p_input jsonb,p_request text,p_actor text) RETURNS jsonb LANGUAGE plpgsql AS $$
DECLARE q finance_same_requests%ROWTYPE; prev finance_same_revisions%ROWTYPE; c finance_same_cases%ROWTYPE; p jsonb; input_value jsonb; basis jsonb; cas text; rev text; ver integer; result jsonb; why text;
BEGIN
 PERFORM finance_same_lock();PERFORM finance_assert_same_definitions(current_schema());
 IF p_action NOT IN('verify','withdraw') OR finance_supply_id(to_jsonb(p_request)) IS DISTINCT FROM true OR finance_supply_id(to_jsonb(p_actor)) IS DISTINCT FROM true OR p_input->>'requestId' IS DISTINCT FROM p_request THEN RAISE EXCEPTION 'Invalid same relation request' USING ERRCODE='22023';END IF;
 SELECT * INTO q FROM finance_same_requests WHERE request_id=p_request;
 IF FOUND THEN
  IF q.action<>p_action OR q.actor_user_id<>p_actor OR q.payload_json IS DISTINCT FROM p_input THEN RAISE EXCEPTION 'Same request conflict' USING ERRCODE='23514';END IF;
  PERFORM finance_same_assert_request(p_request);RETURN q.result_json||'{"replayed":true}'::jsonb;
 END IF;
 IF p_action='verify' THEN
  IF finance_same_input(p_input,true) IS DISTINCT FROM true THEN RAISE EXCEPTION 'Invalid same relation verify' USING ERRCODE='22023';END IF;
  input_value:=p_input-ARRAY['expectedPreviewHash','requestId'];p:=finance_same_candidate(input_value);basis:=p->'_basis';p:=p-'_basis';
  IF p->>'canVerify'<>'true' OR p->>'previewHash' IS DISTINCT FROM p_input->>'expectedPreviewHash' THEN RAISE EXCEPTION 'Same relation preview stale' USING ERRCODE='23514';END IF;
  cas:=p_input->>'caseId';ver:=(p_input->>'expectedVersion')::integer+1;
  IF cas IS NULL THEN cas:='same-'||finance_document_hash(jsonb_build_array(p_input#>>'{draft,subjectId}',finance_same_pair(p_input->'draft')));INSERT INTO finance_same_cases(case_id,subject_id,pair_key,created_request_id,actor_user_id) VALUES(cas,p_input#>>'{draft,subjectId}',finance_same_pair(p_input->'draft'),p_request,p_actor);END IF;
 ELSE
  SELECT * INTO c FROM finance_same_cases WHERE case_id=p_input->>'caseId';SELECT * INTO prev FROM finance_same_revisions WHERE case_id=c.case_id ORDER BY version DESC LIMIT 1;
  IF c.subject_id IS DISTINCT FROM p_input->>'subjectId' OR prev.state IS DISTINCT FROM 'verified_same' OR prev.version IS DISTINCT FROM (p_input->>'expectedVersion')::integer OR prev.revision_id IS DISTINCT FROM p_input->>'expectedRevisionId' OR length(btrim(p_input->>'reason')) NOT BETWEEN 1 AND 2000 OR p_input->>'reason' IS NULL
   OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p_input) key) IS DISTINCT FROM ARRAY['caseId','expectedRevisionId','expectedVersion','reason','requestId','subjectId'] THEN RAISE EXCEPTION 'Same relation withdrawal stale' USING ERRCODE='23514';END IF;
  cas:=c.case_id;ver:=prev.version+1;input_value:=prev.input_json;p:=prev.preview_json;basis:=prev.basis_json;why:=p_input->>'reason';
 END IF;
 rev:='samev-'||finance_document_hash(jsonb_build_array(p_request,p_actor));
 INSERT INTO finance_same_revisions(revision_id,case_id,version,previous_revision_id,schema_version,state,input_json,preview_json,basis_json,proof_hash,withdrawal_reason,request_id,actor_user_id)
 VALUES(rev,cas,ver,CASE WHEN ver=1 THEN NULL ELSE p_input->>'expectedRevisionId' END,'de1b-whole-revision-v1',CASE p_action WHEN 'verify' THEN 'verified_same' ELSE 'withdrawn' END,input_value,p,basis,finance_document_hash(jsonb_build_object('input',input_value,'preview',p,'basis',basis)),why,p_request,p_actor);
 result:=jsonb_build_object('caseId',cas,'revisionId',rev,'version',ver,'state',CASE p_action WHEN 'verify' THEN 'verified_same' ELSE 'withdrawn' END,'replayed',false,'financialUseSupported',false);
 INSERT INTO finance_same_requests(request_id,action,actor_user_id,payload_json,payload_hash,result_json) VALUES(p_request,p_action,p_actor,p_input,finance_document_hash(p_input),result);RETURN result;
END $$;
CREATE OR REPLACE FUNCTION finance_same_list(p_subject text,p_case text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql STABLE AS $$
DECLARE v finance_same_revisions%ROWTYPE; root finance_same_cases%ROWTYPE; result jsonb:='[]'; item jsonb; n integer:=0; count_versions integer; previous integer; cases integer:=0; more boolean:=false;
BEGIN
 FOR root IN SELECT * FROM finance_same_cases WHERE subject_id=p_subject AND (p_case IS NULL OR case_id=p_case) ORDER BY created_at DESC,case_id LIMIT 101 LOOP
  cases:=cases+1;IF cases>100 THEN more:=true;EXIT;END IF;previous:=0;
  SELECT count(*) INTO count_versions FROM finance_same_revisions WHERE case_id=root.case_id;
  IF count_versions=0 THEN RAISE EXCEPTION 'Same relation history missing' USING ERRCODE='55000';END IF;
  FOR v IN SELECT * FROM finance_same_revisions WHERE case_id=root.case_id ORDER BY version LOOP
   PERFORM finance_same_assert_request(v.request_id);IF v.version<>previous+1 THEN RAISE EXCEPTION 'Same relation history gap' USING ERRCODE='55000';END IF;previous:=v.version;
   IF (p_case IS NOT NULL AND v.version>count_versions-100) OR (p_case IS NULL AND v.version=count_versions) THEN
    item:=jsonb_build_array(jsonb_build_object('caseId',v.case_id,'revisionId',v.revision_id,'previousRevisionId',v.previous_revision_id,'version',v.version,'state',v.state,'draft',v.input_json->'draft','preview',v.preview_json,'withdrawalReason',v.withdrawal_reason,'createdAt',v.created_at,'financialUseSupported',false));
    result:=CASE WHEN p_case IS NULL THEN result||item ELSE item||result END;
   END IF;
  END LOOP;
  IF p_case IS NOT NULL AND count_versions>100 THEN more:=true;END IF;
 END LOOP;RETURN jsonb_build_object('records',result,'hasMore',more);
EXCEPTION WHEN serialization_failure OR deadlock_detected THEN RAISE;WHEN OTHERS THEN RAISE EXCEPTION 'Stored same relation list unavailable' USING ERRCODE='55000';
END $$;

CREATE OR REPLACE FUNCTION finance_assert_same_definitions(p_schema text) RETURNS jsonb LANGUAGE plpgsql AS $de1b$
DECLARE expected jsonb := '{"version":"de1b-whole-installation-v1","postgresMajor":17,"functions":[{"cost":"100","kind":"f","name":"finance_same_agreement","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE req text;\nBEGIN\n IF TG_TABLE_NAME=''finance_same_cases'' THEN\n  req:=NEW.created_request_id;\n  IF NOT EXISTS(SELECT 1 FROM finance_same_revisions v WHERE v.case_id=NEW.case_id AND v.version=1 AND v.request_id=NEW.created_request_id) THEN RAISE EXCEPTION ''Orphan same relation root'' USING ERRCODE=''23514'';END IF;\n ELSE req:=NEW.request_id;END IF;\n PERFORM finance_same_assert_request(req);RETURN NULL;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_same_assert_request","rows":"0","binary":null,"config":null,"result":"void","source":"\nDECLARE q finance_same_requests%ROWTYPE; v finance_same_revisions%ROWTYPE; c finance_same_cases%ROWTYPE; prev finance_same_revisions%ROWTYPE; expected jsonb; current_basis jsonb; side text; obs finance_document_observations%ROWTYPE;\nBEGIN\n SELECT * INTO q FROM finance_same_requests WHERE request_id=p_request;SELECT * INTO v FROM finance_same_revisions WHERE request_id=p_request;SELECT * INTO c FROM finance_same_cases WHERE case_id=v.case_id;SELECT * INTO prev FROM finance_same_revisions WHERE revision_id=v.previous_revision_id;\n IF q.request_id IS NULL OR v.revision_id IS NULL OR c.case_id IS NULL OR q.actor_user_id IS DISTINCT FROM v.actor_user_id OR q.payload_hash IS DISTINCT FROM finance_document_hash(q.payload_json)\n  OR finance_supply_id(to_jsonb(q.request_id)) IS DISTINCT FROM true OR finance_supply_id(to_jsonb(q.actor_user_id)) IS DISTINCT FROM true OR finance_same_input(v.input_json) IS DISTINCT FROM true\n  OR c.subject_id IS DISTINCT FROM v.input_json#>>''{draft,subjectId}'' OR c.pair_key IS DISTINCT FROM finance_same_pair(v.input_json->''draft'') OR v.preview_json->''draft'' IS DISTINCT FROM v.input_json->''draft''\n  OR v.proof_hash IS DISTINCT FROM finance_document_hash(jsonb_build_object(''input'',v.input_json,''preview'',v.preview_json,''basis'',v.basis_json))\n  OR v.preview_json->>''schemaVersion'' IS DISTINCT FROM ''de1b-whole-preview-v1'' OR v.preview_json->''financialUseSupported'' IS DISTINCT FROM ''false''::jsonb OR v.preview_json->''canVerify'' IS DISTINCT FROM ''true''::jsonb OR v.preview_json->''issues'' IS DISTINCT FROM ''[]''::jsonb\n  OR v.preview_json->>''previewHash'' IS DISTINCT FROM finance_document_hash(jsonb_build_object(''input'',v.input_json,''result'',v.preview_json-''previewHash'',''basis'',v.basis_json))\n  OR (v.version=1 AND (c.created_request_id<>q.request_id OR c.actor_user_id<>q.actor_user_id)) OR (v.version>1 AND (prev.case_id IS DISTINCT FROM v.case_id OR prev.version IS DISTINCT FROM v.version-1))\n THEN RAISE EXCEPTION ''Same relation archive agreement failed'' USING ERRCODE=''23514'';END IF;\n FOR side IN SELECT unnest(ARRAY[''left'',''right'']) LOOP\n  SELECT * INTO obs FROM finance_document_observations WHERE observation_id=v.input_json#>>ARRAY[''draft'',side,''observationId''];\n  IF obs.observation_id IS NULL OR obs.document_id IS DISTINCT FROM v.input_json#>>ARRAY[''draft'',side,''documentId''] OR obs.subject_id IS DISTINCT FROM c.subject_id OR obs.safe_snapshot_json IS DISTINCT FROM v.basis_json#>ARRAY[side,''snapshot'']\n   OR NOT EXISTS(SELECT 1 FROM finance_document_portions WHERE portion_id=v.input_json#>>ARRAY[''draft'',side,''portionId''] AND document_id=obs.document_id AND locator=''whole'') THEN RAISE EXCEPTION ''Same relation stored observation reference mismatch'' USING ERRCODE=''23514'';END IF;\n  PERFORM finance_document_assert_request(obs.request_id);\n END LOOP;\n expected:=jsonb_build_object(''caseId'',v.case_id,''revisionId'',v.revision_id,''version'',v.version,''state'',v.state,''replayed'',false,''financialUseSupported'',false);\n IF q.result_json IS DISTINCT FROM expected THEN RAISE EXCEPTION ''Same relation request result mismatch'' USING ERRCODE=''23514'';END IF;\n IF v.state=''verified_same'' THEN\n  IF q.action<>''verify'' OR q.payload_json IS DISTINCT FROM v.input_json||jsonb_build_object(''expectedPreviewHash'',v.preview_json->>''previewHash'',''requestId'',q.request_id) THEN RAISE EXCEPTION ''Same relation verify request mismatch'' USING ERRCODE=''23514'';END IF;\n ELSE\n  IF q.action<>''withdraw'' OR prev.state IS DISTINCT FROM ''verified_same'' OR v.input_json IS DISTINCT FROM prev.input_json OR v.preview_json IS DISTINCT FROM prev.preview_json OR v.basis_json IS DISTINCT FROM prev.basis_json\n   OR q.payload_json IS DISTINCT FROM jsonb_build_object(''subjectId'',c.subject_id,''caseId'',c.case_id,''expectedVersion'',prev.version,''expectedRevisionId'',prev.revision_id,''reason'',v.withdrawal_reason,''requestId'',q.request_id) THEN RAISE EXCEPTION ''Same relation withdrawal request mismatch'' USING ERRCODE=''23514'';END IF;\n END IF;\n IF v.apply_xid=pg_current_xact_id_if_assigned() AND v.state=''verified_same'' THEN\n  current_basis:=finance_same_candidate(v.input_json,v.case_id)->''_basis'';\n  IF current_basis IS DISTINCT FROM v.basis_json THEN RAISE EXCEPTION ''Same relation source changed before commit'' USING ERRCODE=''23514'';END IF;\n END IF;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_request text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"text","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_same_c_target","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\nDECLARE c vat_followup_review_consumptions%ROWTYPE; a vat_followup_legacy_archives%ROWTYPE; rr jsonb; form jsonb; pairs jsonb; h text; subject text;\nBEGIN\n SELECT * INTO STRICT c FROM vat_followup_review_consumptions WHERE consumption_id=p_id;\n IF (c.basis_confirmation_id IS NULL)=(c.legacy_archive_id IS NULL) THEN RAISE EXCEPTION ''C target identity invalid'';END IF;\n IF c.basis_confirmation_id IS NOT NULL THEN\n  h:=vat_post_confirmed_return_hash(c.basis_confirmation_id);\n  SELECT b.subject_id,r.form_json INTO STRICT subject,form FROM vat_filing_return_confirmations x JOIN vat_filing_return_revisions r ON r.return_id=x.return_id JOIN vat_filing_basis_snapshots b ON b.snapshot_id=r.basis_snapshot_id WHERE x.confirmation_id=c.basis_confirmation_id;\n  IF subject IS DISTINCT FROM p_subject OR form#>>''{followupConsumption,application,subjectId}'' IS DISTINCT FROM p_subject OR h IS DISTINCT FROM c.calculation_hash THEN RAISE EXCEPTION ''C confirmation subject/hash invalid'';END IF;\n ELSE\n  SELECT * INTO STRICT a FROM vat_followup_legacy_archives WHERE archive_id=c.legacy_archive_id;\n  SELECT to_jsonb(r) INTO STRICT rr FROM vat_returns r WHERE r.return_id=a.return_id;\n  form:=vat_followup_validate_form_v2(a.form_json,''legacy'',NULL);\n  SELECT COALESCE(jsonb_agg(x.payload_json ORDER BY x.payload_json->>''revisionId'' COLLATE \"C\",x.pair_line_no),''[]'') INTO pairs FROM vat_followup_review_consumptions x WHERE x.legacy_archive_id=a.archive_id;\n  IF a.schema_version<>''vat-return-legacy-v2'' OR a.row_json IS DISTINCT FROM rr OR a.row_json->''form_json'' IS DISTINCT FROM a.form_json OR rr->>''status''<>''confirmed'' OR rr->>''period_kind''<>''final''\n   OR rr->>''return_id'' IS DISTINCT FROM a.return_id OR rr->>''confirmed_by'' IS DISTINCT FROM a.created_by OR form#>>''{application,subjectId}'' IS DISTINCT FROM p_subject\n   OR a.calculation_hash IS DISTINCT FROM form->>''calculationHash'' OR c.calculation_hash IS DISTINCT FROM a.calculation_hash OR form->''pairs'' IS DISTINCT FROM pairs\n   OR rr->''period_year'' IS DISTINCT FROM form#>''{application,year}'' OR rr->''period_term'' IS DISTINCT FROM form#>''{application,term}'' OR rr->>''date_from'' IS DISTINCT FROM form#>>''{application,dateFrom}'' OR rr->>''date_to'' IS DISTINCT FROM form#>>''{application,dateTo}'' OR a.form_json->''blockingIssues'' IS DISTINCT FROM ''[]''::jsonb\n   OR EXISTS(SELECT 1 FROM vat_followup_review_consumptions x LEFT JOIN vat_followup_review_revisions v USING(revision_id) LEFT JOIN vat_followup_review_roots r USING(review_id)\n     WHERE x.legacy_archive_id=a.archive_id AND (x.basis_confirmation_id IS NOT NULL OR x.created_by IS DISTINCT FROM a.created_by OR x.calculation_hash IS DISTINCT FROM a.calculation_hash OR x.payload_json->>''revisionId'' IS DISTINCT FROM x.revision_id OR x.payload_json->''pairLineNo'' IS DISTINCT FROM to_jsonb(x.pair_line_no) OR v.schema_version IS DISTINCT FROM ''vat-followup-review-v1'' OR v.state IS DISTINCT FROM ''verified'' OR v.payload_hash IS DISTINCT FROM vat_followup_hash(v.payload_json) OR v.payload_json#>ARRAY[''pairs'',x.pair_line_no::text] IS DISTINCT FROM x.payload_json->''pair'' OR r.subject_id IS DISTINCT FROM p_subject)) THEN RAISE EXCEPTION ''C legacy confirmation integrity invalid'';END IF;\n  h:=a.calculation_hash;\n END IF;\n RETURN jsonb_build_object(''consumptionId'',c.consumption_id,''revisionId'',c.revision_id,''pairLineNo'',c.pair_line_no,''basisConfirmationId'',c.basis_confirmation_id,''legacyArchiveId'',c.legacy_archive_id,''calculationHash'',h,''formHash'',finance_document_hash(form));\nEXCEPTION WHEN serialization_failure OR deadlock_detected THEN RAISE;WHEN OTHERS THEN RAISE EXCEPTION ''C target stored evidence unavailable'' USING ERRCODE=''55000'';\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_id text, p_subject text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"s","argumentTypes":"text, text","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_same_candidate","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\nDECLARE d jsonb; l jsonb; r jsonb; issues jsonb:=''[]''; basis jsonb; result jsonb; last_row finance_same_revisions%ROWTYPE; root_row finance_same_cases%ROWTYPE;\n connected text[]; connected_docs text[]; e record; f jsonb; g jsonb; c_refs jsonb:=''[]''; graph jsonb:=''[]''; distinct_links jsonb:=''[]''; proof jsonb; refdoc jsonb;\nBEGIN\n IF finance_same_input(p_input) IS DISTINCT FROM true THEN RAISE EXCEPTION ''Invalid same relation input'' USING ERRCODE=''22023'';END IF;\n d:=p_input->''draft'';l:=finance_same_side(d,d->''left'');r:=finance_same_side(d,d->''right'');issues:=(l->''issues'')||(r->''issues'');\n IF d#>>''{left,portionId}''=d#>>''{right,portionId}'' OR d#>>''{left,documentId}''=d#>>''{right,documentId}'' THEN issues:=issues||finance_document_issue(''same_identity_self'',''별칭이 합쳐진 같은 문서 자체를 중복 확인할 수 없습니다.'');END IF;\n IF l->''summary'' IS NULL OR r->''summary'' IS NULL OR l#>''{summary,supply}'' IS DISTINCT FROM r#>''{summary,supply}'' OR l#>''{summary,tax}'' IS DISTINCT FROM r#>''{summary,tax}'' OR l#>''{summary,total}'' IS DISTINCT FROM r#>''{summary,total}'' OR l#>''{summary,direction}'' IS DISTINCT FROM r#>''{summary,direction}'' THEN issues:=issues||finance_document_issue(''whole_amount_mismatch'',''문서 전체의 방향·공급가액·세액·합계가 일치해야 합니다. 부분은 아직 지원하지 않습니다.'');END IF;\n IF l->>''counterparty'' IS DISTINCT FROM r->>''counterparty'' THEN issues:=issues||finance_document_issue(''same_counterparty_mismatch'',''두 문서의 거래처가 다릅니다.'');END IF;\n refdoc:=finance_same_document(d#>>''{evidence,documentId}'',d->>''subjectId'',d#>>''{evidence,evidenceHash}'');IF refdoc IS NULL THEN issues:=issues||finance_document_issue(''evidence_unavailable'',''같은 회사의 보관 증빙과 해시를 확인하세요.'');END IF;\n IF p_input->>''caseId'' IS NOT NULL THEN\n  SELECT * INTO root_row FROM finance_same_cases WHERE case_id=p_input->>''caseId'';SELECT * INTO last_row FROM finance_same_revisions WHERE case_id=p_input->>''caseId'' ORDER BY version DESC LIMIT 1;\n  IF root_row.subject_id IS DISTINCT FROM d->>''subjectId'' OR root_row.pair_key IS DISTINCT FROM finance_same_pair(d) OR last_row.version IS DISTINCT FROM (p_input->>''expectedVersion'')::integer OR last_row.revision_id IS DISTINCT FROM p_input->>''expectedRevisionId'' THEN issues:=issues||finance_document_issue(''same_revision_stale'',''현재 관계의 최신 판을 다시 선택하세요.'');END IF;\n ELSIF EXISTS(SELECT 1 FROM finance_same_cases WHERE subject_id=d->>''subjectId'' AND pair_key=finance_same_pair(d) AND case_id IS DISTINCT FROM p_ignore_case) THEN issues:=issues||finance_document_issue(''same_case_exists'',''이미 기록된 관계의 최신 판으로 검토하세요.'');END IF;\n WITH RECURSIVE edges AS (SELECT v.input_json#>>''{draft,left,portionId}'' a,v.input_json#>>''{draft,right,portionId}'' b FROM finance_same_revisions v JOIN finance_same_cases c USING(case_id)\n  WHERE c.subject_id=d->>''subjectId'' AND v.state=''verified_same'' AND c.case_id IS DISTINCT FROM COALESCE(p_input->>''caseId'',p_ignore_case) AND NOT EXISTS(SELECT 1 FROM finance_same_revisions n WHERE n.case_id=v.case_id AND n.version>v.version)),\n walk(p) AS (SELECT unnest(ARRAY[d#>>''{left,portionId}'',d#>>''{right,portionId}'']) UNION SELECT CASE WHEN edge_row.a=w.p THEN edge_row.b ELSE edge_row.a END FROM walk w JOIN edges edge_row ON edge_row.a=w.p OR edge_row.b=w.p)\n SELECT array_agg(p ORDER BY p) INTO connected FROM walk;\n SELECT array_agg(DISTINCT document_id ORDER BY document_id) INTO connected_docs FROM finance_document_portions WHERE portion_id=ANY(connected);\n FOR e IN SELECT v.* FROM finance_same_revisions v JOIN finance_same_cases c USING(case_id) WHERE c.subject_id=d->>''subjectId'' AND v.state=''verified_same'' AND c.case_id IS DISTINCT FROM COALESCE(p_input->>''caseId'',p_ignore_case)\n  AND NOT EXISTS(SELECT 1 FROM finance_same_revisions n WHERE n.case_id=v.case_id AND n.version>v.version) AND (v.input_json#>>''{draft,left,portionId}''=ANY(connected) OR v.input_json#>>''{draft,right,portionId}''=ANY(connected)) ORDER BY v.revision_id LOOP\n  f:=finance_same_side(e.input_json->''draft'',e.input_json#>''{draft,left}'');g:=finance_same_side(e.input_json->''draft'',e.input_json#>''{draft,right}'');\n  IF f->''issues''<>''[]''::jsonb OR g->''issues''<>''[]''::jsonb OR f IS DISTINCT FROM e.basis_json->''left'' OR g IS DISTINCT FROM e.basis_json->''right'' THEN issues:=issues||finance_document_issue(''same_graph_stale'',''전이에 사용하는 기존 관계의 원천을 먼저 재검토하세요.'');END IF;\n  graph:=graph||jsonb_build_array(jsonb_build_object(''revisionId'',e.revision_id,''proofHash'',e.proof_hash));\n END LOOP;\n FOR e IN SELECT t.* FROM transaction_links t WHERE t.relation=''distinct'' AND t.state=''active''\n  AND EXISTS(SELECT 1 FROM finance_document_sources s WHERE s.document_id=ANY(connected_docs) AND s.source_kind=t.left_kind AND s.source_id=t.left_id)\n  AND EXISTS(SELECT 1 FROM finance_document_sources s JOIN finance_document_registry d0 USING(document_id) WHERE s.document_id=ANY(connected_docs) AND (s.source_kind=t.right_kind AND s.source_id=t.right_id OR t.canonical_invoice_key=''invoice:''||(d0.descriptor_json->>1))) ORDER BY t.link_id LOOP\n  -- A stale active declaration is not erased or treated as proof of sameness.\n  distinct_links:=distinct_links||jsonb_build_array(jsonb_build_object(''linkId'',e.link_id,''snapshotHash'',finance_document_hash(to_jsonb(e)),''leftHash'',e.left_hash,''rightHash'',e.right_hash));\n  issues:=issues||finance_document_issue(''distinct_relation_unresolved'',''같은 연결 성분에 별개 공급 선언이 있습니다. 정확 원천과 선언의 현재 근거를 먼저 해결하세요.'');\n END LOOP;\n FOR e IN SELECT p.*,v.state,v.payload_hash,v.payload_json,v.review_id,root.subject_id,c.consumption_id,c.payload_json AS consumption,c.basis_confirmation_id,c.legacy_archive_id,c.calculation_hash FROM vat_followup_review_pairs p\n  JOIN vat_followup_review_revisions v USING(revision_id) JOIN vat_followup_review_roots root USING(review_id)\n  LEFT JOIN vat_followup_review_consumptions c ON c.revision_id=p.revision_id AND c.pair_line_no=p.line_no\n  WHERE root.subject_id=d->>''subjectId'' AND (c.consumption_id IS NOT NULL OR v.state=''verified'' AND NOT EXISTS(SELECT 1 FROM vat_followup_review_revisions n WHERE n.review_id=v.review_id AND n.version>v.version))\n   AND (EXISTS(SELECT 1 FROM finance_document_sources s WHERE s.document_id=ANY(connected_docs) AND s.source_kind=''card'' AND s.source_id=p.card_source_id) OR EXISTS(SELECT 1 FROM finance_document_sources s WHERE s.document_id=ANY(connected_docs) AND s.source_kind=''hometax'' AND s.source_id=p.invoice_source_id)) ORDER BY p.revision_id,p.line_no LOOP\n  IF e.state<>''verified'' OR e.payload_hash IS DISTINCT FROM vat_followup_hash(e.payload_json) OR e.payload_json#>ARRAY[''pairs'',e.line_no::text] IS DISTINCT FROM e.pair_json THEN RAISE EXCEPTION ''C pair archive mismatch'' USING ERRCODE=''55000'';END IF;\n  IF e.pair_json->''databaseProof'' IS DISTINCT FROM vat_followup_database_proof(e.card_source_id,e.invoice_source_id,e.legacy_return_id,e.past_basis_snapshot_id,e.past_fact_revision_id) THEN issues:=issues||finance_document_issue(''c_source_stale'',''관련 C 정확 쌍의 현재 원천 근거를 재검토하세요.'');END IF;\n  IF e.consumption_id IS NOT NULL THEN\n   proof:=finance_same_c_target(e.consumption_id,d->>''subjectId'');\n  ELSE proof:=NULL;END IF;\n  c_refs:=c_refs||jsonb_build_array(jsonb_build_object(''revisionId'',e.revision_id,''pairLineNo'',e.line_no,''pairHash'',finance_document_hash(e.pair_json),''consumptionId'',e.consumption_id,''targetProof'',proof,''claimedSupply'',NULL,''claimedTax'',e.pair_json#>''{past,claim,claimedTax}''));\n  IF EXISTS(SELECT 1 FROM finance_document_sources s WHERE s.document_id=ANY(connected_docs) AND s.source_kind=''card'' AND s.source_id=e.card_source_id) AND EXISTS(SELECT 1 FROM finance_document_sources s WHERE s.document_id=ANY(connected_docs) AND s.source_kind=''hometax'' AND s.source_id=e.invoice_source_id) THEN issues:=issues||finance_document_issue(''c_distinct_conflict'',''정확한 C 별개 공급 쌍과 같은 공급 관계가 모순됩니다.'');END IF;\n END LOOP;\n basis:=jsonb_build_object(''version'',''de1b-whole-basis-v1'',''left'',l,''right'',r,''evidence'',refdoc,''graph'',graph,''distinctLinks'',distinct_links,''cReferences'',c_refs);\n result:=jsonb_build_object(''schemaVersion'',''de1b-whole-preview-v1'',''draft'',d,''canVerify'',jsonb_array_length(issues)=0,''issues'',issues,''left'',l->''summary'',''right'',r->''summary'',''timeDiagnostics'',(l->''times'')||(r->''times''),''financialUseSupported'',false);\n RETURN result||jsonb_build_object(''previewHash'',finance_document_hash(jsonb_build_object(''input'',p_input,''result'',result,''basis'',basis)),''_basis'',basis);\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_input jsonb, p_ignore_case text DEFAULT NULL::text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"s","argumentTypes":"jsonb, text","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_same_card_source","rows":"0","binary":null,"config":null,"result":"text","source":"\nDECLARE m jsonb; fields jsonb;\nBEGIN\n m:=finance_same_merchant(p);fields:=jsonb_build_array(''card-tax-v1'',p->>''card_txn_id'',p->>''card_id'',p->>''approval_type'',p->>''approval_num'',p->>''approved_at'',p->>''amount_total'',p->>''supply_amount'',p->>''tax_amount'',p->>''service_charge'',CASE WHEN m IS NULL THEN p->>''store_corp_num'' ELSE m->>''effectiveCorpNum'' END,p->>''store_tax_type'',p->>''category_key'',p->>''excluded'');\n IF m IS NOT NULL THEN fields:=fields||jsonb_build_array(jsonb_build_array(''merchant-correction-v1'',m->>''eventId'',m->''version'',m->>''evidenceHash'',m->>''status'',m->''issues''));END IF;\n RETURN vat_followup_hash(fields);\nEND\n","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p jsonb","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"s","argumentTypes":"jsonb","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_same_document","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\nDECLARE d vat_filing_documents%ROWTYPE;\nBEGIN\n SELECT * INTO d FROM vat_filing_documents WHERE document_id=p_id;\n IF NOT FOUND THEN RETURN NULL;END IF;\n IF d.subject_id<>p_subject OR d.content_sha256 IS DISTINCT FROM p_hash THEN RETURN NULL;END IF;\n IF d.size_bytes IS DISTINCT FROM octet_length(d.content_bytes) OR d.content_sha256 IS DISTINCT FROM encode(sha256(d.content_bytes),''hex'') THEN RAISE EXCEPTION ''Same relation document integrity failure'' USING ERRCODE=''55000'';END IF;\n RETURN jsonb_build_object(''documentId'',d.document_id,''subjectId'',d.subject_id,''evidenceHash'',d.content_sha256,''sizeBytes'',d.size_bytes);\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_id text, p_subject text, p_hash text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"s","argumentTypes":"text, text, text","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_same_immutable","rows":"0","binary":null,"config":null,"result":"trigger","source":" BEGIN RAISE EXCEPTION ''Same relation history is immutable'' USING ERRCODE=''23514'';END ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_same_input","rows":"0","binary":null,"config":null,"result":"boolean","source":"\nDECLARE d jsonb; r jsonb; k text; expected text[];\nBEGIN\n expected:=ARRAY[''draft'',''caseId'',''expectedVersion'',''expectedRevisionId''];IF p_save THEN expected:=expected||ARRAY[''expectedPreviewHash'',''requestId''];END IF;\n IF jsonb_typeof(p)<>''object'' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p) key) IS DISTINCT FROM (SELECT array_agg(x ORDER BY x) FROM unnest(expected) x)\n  OR NOT vat_followup_money(p->''expectedVersion'') OR (p->>''expectedVersion'')::numeric>2147483646 THEN RETURN false;END IF;\n IF p->''expectedVersion''=''0''::jsonb THEN IF p->''caseId''<>''null''::jsonb OR p->''expectedRevisionId''<>''null''::jsonb THEN RETURN false;END IF;\n ELSIF finance_supply_id(p->''caseId'') IS DISTINCT FROM true OR finance_supply_id(p->''expectedRevisionId'') IS DISTINCT FROM true THEN RETURN false;END IF;\n IF p_save AND (finance_supply_id(p->''requestId'') IS DISTINCT FROM true OR COALESCE(p->>''expectedPreviewHash'','''') !~ ''^[a-f0-9]{64}$'') THEN RETURN false;END IF;\n d:=p->''draft'';IF jsonb_typeof(d)<>''object'' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(d) key) IS DISTINCT FROM ARRAY[''evidence'',''left'',''reason'',''reviewRevisionId'',''right'',''subjectId'']\n  OR finance_supply_id(d->''subjectId'') IS DISTINCT FROM true OR finance_supply_id(d->''reviewRevisionId'') IS DISTINCT FROM true OR length(btrim(d->>''reason'')) NOT BETWEEN 1 AND 2000 OR d->>''reason'' IS NULL THEN RETURN false;END IF;\n FOR k IN SELECT unnest(ARRAY[''left'',''right'']) LOOP r:=d->k;\n  IF jsonb_typeof(r)<>''object'' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(r) key) IS DISTINCT FROM ARRAY[''documentId'',''observationId'',''portionId'']\n   OR finance_supply_id(r->''documentId'') IS DISTINCT FROM true OR finance_supply_id(r->''portionId'') IS DISTINCT FROM true OR finance_supply_id(r->''observationId'') IS DISTINCT FROM true THEN RETURN false;END IF;\n END LOOP;\n r:=d->''evidence'';IF jsonb_typeof(r)<>''object'' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(r) key) IS DISTINCT FROM ARRAY[''documentId'',''evidenceHash'',''location'']\n  OR finance_supply_id(r->''documentId'') IS DISTINCT FROM true OR COALESCE(r->>''evidenceHash'','''') !~ ''^[a-f0-9]{64}$'' OR length(btrim(r->>''location'')) NOT BETWEEN 1 AND 2000 OR r->>''location'' IS NULL THEN RETURN false;END IF;\n RETURN true;\nEXCEPTION WHEN OTHERS THEN RETURN false;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p jsonb, p_save boolean DEFAULT false","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"jsonb, boolean","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_same_insert","rows":"0","binary":null,"config":null,"result":"trigger","source":"\nDECLARE prev finance_same_revisions%ROWTYPE; root finance_same_cases%ROWTYPE; p jsonb;\nBEGIN\n PERFORM finance_same_lock();PERFORM finance_assert_same_definitions(current_schema());\n IF TG_TABLE_NAME=''finance_same_revisions'' THEN\n  SELECT * INTO root FROM finance_same_cases WHERE case_id=NEW.case_id;SELECT * INTO prev FROM finance_same_revisions WHERE case_id=NEW.case_id ORDER BY version DESC LIMIT 1;\n  IF NEW.apply_xid IS DISTINCT FROM pg_current_xact_id() OR NEW.version<>COALESCE(prev.version,0)+1 OR NEW.previous_revision_id IS DISTINCT FROM prev.revision_id OR finance_same_input(NEW.input_json) IS DISTINCT FROM true OR root.subject_id IS DISTINCT FROM NEW.input_json#>>''{draft,subjectId}'' OR root.pair_key IS DISTINCT FROM finance_same_pair(NEW.input_json->''draft'') THEN RAISE EXCEPTION ''Same relation root/version mismatch'' USING ERRCODE=''23514'';END IF;\n  IF NEW.state=''verified_same'' THEN\n   p:=finance_same_candidate(NEW.input_json,NEW.case_id);\n   IF p->>''canVerify''<>''true'' OR NEW.preview_json IS DISTINCT FROM p-''_basis'' OR NEW.basis_json IS DISTINCT FROM p->''_basis'' THEN RAISE EXCEPTION ''Same relation current proof mismatch'' USING ERRCODE=''23514'';END IF;\n  ELSE\n   IF prev.state IS DISTINCT FROM ''verified_same'' OR NEW.input_json IS DISTINCT FROM prev.input_json OR NEW.preview_json IS DISTINCT FROM prev.preview_json OR NEW.basis_json IS DISTINCT FROM prev.basis_json THEN RAISE EXCEPTION ''Invalid same relation withdrawal'' USING ERRCODE=''23514'';END IF;\n  END IF;\n END IF;\n RETURN NEW;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_same_list","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\nDECLARE v finance_same_revisions%ROWTYPE; root finance_same_cases%ROWTYPE; result jsonb:=''[]''; item jsonb; n integer:=0; count_versions integer; previous integer; cases integer:=0; more boolean:=false;\nBEGIN\n FOR root IN SELECT * FROM finance_same_cases WHERE subject_id=p_subject AND (p_case IS NULL OR case_id=p_case) ORDER BY created_at DESC,case_id LIMIT 101 LOOP\n  cases:=cases+1;IF cases>100 THEN more:=true;EXIT;END IF;previous:=0;\n  SELECT count(*) INTO count_versions FROM finance_same_revisions WHERE case_id=root.case_id;\n  IF count_versions=0 THEN RAISE EXCEPTION ''Same relation history missing'' USING ERRCODE=''55000'';END IF;\n  FOR v IN SELECT * FROM finance_same_revisions WHERE case_id=root.case_id ORDER BY version LOOP\n   PERFORM finance_same_assert_request(v.request_id);IF v.version<>previous+1 THEN RAISE EXCEPTION ''Same relation history gap'' USING ERRCODE=''55000'';END IF;previous:=v.version;\n   IF (p_case IS NOT NULL AND v.version>count_versions-100) OR (p_case IS NULL AND v.version=count_versions) THEN\n    item:=jsonb_build_array(jsonb_build_object(''caseId'',v.case_id,''revisionId'',v.revision_id,''previousRevisionId'',v.previous_revision_id,''version'',v.version,''state'',v.state,''draft'',v.input_json->''draft'',''preview'',v.preview_json,''withdrawalReason'',v.withdrawal_reason,''createdAt'',v.created_at,''financialUseSupported'',false));\n    result:=CASE WHEN p_case IS NULL THEN result||item ELSE item||result END;\n   END IF;\n  END LOOP;\n  IF p_case IS NOT NULL AND count_versions>100 THEN more:=true;END IF;\n END LOOP;RETURN jsonb_build_object(''records'',result,''hasMore'',more);\nEXCEPTION WHEN serialization_failure OR deadlock_detected THEN RAISE;WHEN OTHERS THEN RAISE EXCEPTION ''Stored same relation list unavailable'' USING ERRCODE=''55000'';\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_subject text, p_case text DEFAULT NULL::text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"s","argumentTypes":"text, text","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_same_lock","rows":"0","binary":null,"config":null,"result":"void","source":"\nBEGIN\n PERFORM finance_document_write_lock();\n LOCK TABLE finance_document_registry,finance_document_sources,finance_document_portions,finance_document_observations,finance_document_requests,\n vat_filing_documents,card_tax_reviews,card_merchant_corrections,vat_followup_review_roots,vat_followup_review_revisions,vat_followup_review_pairs,vat_followup_review_consumptions,\n vat_filing_return_confirmations,vat_filing_return_revisions,vat_filing_basis_snapshots,vat_filing_fact_revisions,vat_filing_basis_consumptions,\n vat_followup_legacy_archives,vat_returns,transaction_links,transaction_invoice_recognitions IN SHARE MODE;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_same_merchant","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\nDECLARE e card_merchant_corrections%ROWTYPE; keys text[]:=ARRAY[''card_txn_id'',''card_id'',''approval_type'',''approval_num'',''approved_at'',''amount_total'',''supply_amount'',''tax_amount'',''service_charge'',''store_corp_num'',''store_name'',''store_tax_type''];\n current_basis jsonb; ordered_text text; h text; issues jsonb:=''[]''; effective text; evidence_hash text;\nBEGIN\n SELECT * INTO e FROM card_merchant_corrections WHERE card_txn_id=p->>''card_txn_id'' ORDER BY version DESC LIMIT 1;\n IF NOT FOUND THEN RETURN NULL;END IF;\n -- Existing A uses JSON.stringify on this fixed insertion-ordered string/null object.\n SELECT jsonb_object_agg(k,to_jsonb(p->>k)), ''{''||string_agg(to_jsonb(k)::text||'':''||COALESCE(to_jsonb(p->>k)::text,''null''),'','' ORDER BY ord)||''}'' INTO current_basis,ordered_text FROM unnest(keys) WITH ORDINALITY x(k,ord);\n h:=encode(sha256(convert_to(ordered_text,''UTF8'')),''hex'');\n IF e.original_source_hash IS DISTINCT FROM h THEN issues:=issues||jsonb_build_array(''사업자번호 정정 후 수집 원천이 달라졌습니다. 정정 증빙을 다시 검토하세요.'');END IF;\n SELECT ''{''||string_agg(to_jsonb(k)::text||'':''||COALESCE((e.original_basis->k)::text,''null''),'','' ORDER BY ord)||''}'' INTO ordered_text FROM unnest(keys) WITH ORDINALITY x(k,ord);\n IF encode(sha256(convert_to(ordered_text,''UTF8'')),''hex'') IS DISTINCT FROM e.original_source_hash THEN issues:=issues||jsonb_build_array(''사업자번호 정정의 저장 원본 근거가 일치하지 않습니다.'');END IF;\n effective:=CASE WHEN e.action=''correct'' THEN e.corp_num ELSE p->>''store_corp_num'' END;\n evidence_hash:=vat_followup_hash(jsonb_build_array(e.event_id,e.version,e.action,e.corp_num,e.original_source_hash,e.reason,e.evidence,e.actor_user_id,e.reviewed_by,e.created_at));\n RETURN jsonb_build_object(''eventId'',e.event_id,''version'',e.version,''action'',e.action,''originalCorpNum'',p->>''store_corp_num'',''effectiveCorpNum'',effective,\n  ''status'',CASE WHEN jsonb_array_length(issues)>0 THEN ''review_required'' WHEN e.action=''correct'' THEN ''corrected'' ELSE ''original'' END,''originalSourceHash'',e.original_source_hash,''currentSourceHash'',h,''evidenceHash'',evidence_hash,''issues'',issues,''originalBasis'',e.original_basis);\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p jsonb","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"s","argumentTypes":"jsonb","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_same_pair","rows":"0","binary":null,"config":null,"result":"text","source":"\n SELECT finance_document_hash(to_jsonb(ARRAY[least(p_draft#>>''{left,portionId}'',p_draft#>>''{right,portionId}''),greatest(p_draft#>>''{left,portionId}'',p_draft#>>''{right,portionId}'')]))\n","strict":false,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"p_draft jsonb","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"jsonb","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_same_preview","rows":"0","binary":null,"config":null,"result":"jsonb","source":" SELECT finance_same_candidate(p_input)-''_basis'' ","strict":false,"support":"0","language":"sql","parallel":"u","variadic":"0","arguments":"p_input jsonb","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"s","argumentTypes":"jsonb","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_same_side","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\nDECLARE o finance_document_observations%ROWTYPE; candidate jsonb; issues jsonb:=''[]''; times jsonb:=''[]''; reversals jsonb:=''[]''; merchant jsonb; reversal_merchant jsonb; x jsonb; c jsonb; cr jsonb; orig_review jsonb; rev_review jsonb; diag jsonb; company jsonb; source_hash text; original_hash text; n numeric; counterparty text;\nBEGIN\n SELECT * INTO o FROM finance_document_observations WHERE observation_id=p_ref->>''observationId'' AND document_id=p_ref->>''documentId'' AND subject_id=p_draft->>''subjectId'';\n IF NOT FOUND THEN RETURN jsonb_build_object(''issues'',finance_document_issue(''observation_missing'',''정확한 문서 관측을 선택하세요.''),''summary'',NULL,''times'',times);END IF;\n BEGIN PERFORM finance_document_assert_request(o.request_id);EXCEPTION WHEN serialization_failure OR deadlock_detected THEN RAISE;WHEN OTHERS THEN RAISE EXCEPTION ''Stored document proof unavailable'' USING ERRCODE=''55000'';END;\n IF NOT EXISTS(SELECT 1 FROM finance_document_portions WHERE document_id=o.document_id AND portion_id=p_ref->>''portionId'' AND locator=''whole'')\n  OR EXISTS(SELECT 1 FROM finance_document_observations WHERE document_id=o.document_id AND version>o.version) THEN issues:=issues||finance_document_issue(''observation_stale'',''최신 문서 전체 관측을 선택하세요.'');END IF;\n candidate:=finance_document_candidate(o.subject_id,p_draft->>''reviewRevisionId'',o.source_kind,o.source_id);\n IF candidate->>''canRegister'' IS DISTINCT FROM ''true'' OR candidate->''_safeSnapshot'' IS DISTINCT FROM o.safe_snapshot_json OR o.review_revision_id IS DISTINCT FROM p_draft->>''reviewRevisionId''\n  OR candidate->>''documentId'' IS DISTINCT FROM o.document_id OR candidate->>''portionId'' IS DISTINCT FROM p_ref->>''portionId''\n THEN issues:=issues||finance_document_issue(''source_observation_changed'',''원천·회사·기록판이 바뀌었습니다. 양쪽을 같은 최신 기록판으로 재관측하세요.'');END IF;\n company:=candidate#>''{_safeSnapshot,subject}'';\n x:=candidate#>''{_safeSnapshot,sourceSnapshots,0}'';counterparty:=CASE WHEN x->>''kind''=''card'' THEN x->>''storeCorpNum'' WHEN x->>''direction''=''purchase'' THEN x->>''supplier'' ELSE x->>''recipient'' END;\n IF counterparty IS NULL OR counterparty !~ ''^[0-9]{10}$'' THEN issues:=issues||finance_document_issue(''same_counterparty_unavailable'',''정확한 거래처 번호를 확인하세요.'');END IF;\n IF finance_same_document(substr(company->>''evidenceRef'',14),o.subject_id,company->>''evidenceHash'') IS NULL OR left(COALESCE(company->>''evidenceRef'',''''),13)<>''vat-document:'' THEN issues:=issues||finance_document_issue(''subject_evidence_unavailable'',''해당일 회사 기준의 보관 증빙을 확인하세요.'');END IF;\n FOR x IN SELECT value FROM jsonb_array_elements(COALESCE(candidate#>''{_safeSnapshot,sourceSnapshots}'',''[]'')) LOOP\n  IF x->>''kind''=''card'' THEN\n   SELECT to_jsonb(t) INTO c FROM card_transactions t WHERE card_txn_id=x->>''id'';\n   merchant:=finance_same_merchant(c);\n   IF merchant IS NOT NULL AND (merchant->>''status''=''review_required'' OR merchant->>''effectiveCorpNum'' IS DISTINCT FROM c->>''store_corp_num'') THEN issues:=issues||finance_document_issue(''merchant_correction_scope'',''현재 가맹점 정정 근거가 원문 whole과 다르거나 재검토가 필요합니다. 이 첫 범위는 정정 번호를 반영한 관계를 지원하지 않습니다. 재관측만으로 해결되지 않습니다.'');END IF;\n   diag:=finance_same_time(x->>''id'',c#>''{raw_json,ApprovalDT}'',c->>''approved_at'');times:=times||jsonb_build_array(diag);\n   IF diag->>''status''<>''matched'' THEN issues:=issues||finance_document_issue(''card_time_''||(diag->>''status''),''카드 원문 승인일시의 투영과 근거를 확인하세요.'');END IF;\n   SELECT to_jsonb(r) INTO orig_review FROM card_tax_reviews r WHERE card_txn_id=c->>''card_txn_id'';\n   source_hash:=finance_same_card_source(c);original_hash:=vat_followup_hash(jsonb_build_array(source_hash,orig_review->>''source_hash'',orig_review->''decision'',orig_review->>''tax_date'',orig_review->>''reason'',orig_review->>''evidence_ref''));\n   FOR cr IN SELECT to_jsonb(t) FROM card_transactions t LEFT JOIN card_tax_reviews r ON r.card_txn_id=t.card_txn_id\n    WHERE COALESCE(t.excluded,0)=0 AND (r.original_card_txn_id=c->>''card_txn_id'' OR btrim(t.approval_type) IN(''취소'',''부분취소'',''환불'') AND t.card_id=c->>''card_id'' AND t.approval_num=c->>''approval_num'') ORDER BY t.card_txn_id LOOP\n    SELECT to_jsonb(r) INTO rev_review FROM card_tax_reviews r WHERE card_txn_id=cr->>''card_txn_id'';\n    reversal_merchant:=finance_same_merchant(cr);\n    diag:=finance_same_time(cr->>''card_txn_id'',cr#>''{raw_json,ApprovalDT}'',cr->>''approved_at'');times:=times||jsonb_build_array(diag);\n    reversals:=reversals||jsonb_build_array(jsonb_build_object(''sourceId'',cr->>''card_txn_id'',''sourceHash'',finance_document_hash(cr-ARRAY[''raw_json'']),''rawHash'',finance_document_hash(cr->''raw_json''),''review'',rev_review,''time'',diag,''merchant'',reversal_merchant));\n    IF diag->>''status''<>''matched'' OR COALESCE(btrim(cr->>''approval_type''),'''') NOT IN(''취소'',''부분취소'',''환불'') OR rev_review->>''original_card_txn_id'' IS DISTINCT FROM c->>''card_txn_id'' OR cr->>''card_id'' IS DISTINCT FROM c->>''card_id'' OR cr->>''store_corp_num'' IS DISTINCT FROM c->>''store_corp_num''\n     OR rev_review->>''source_hash'' IS DISTINCT FROM finance_same_card_source(cr) OR rev_review->>''original_source_hash'' IS DISTINCT FROM original_hash\n     OR orig_review->>''source_hash'' IS DISTINCT FROM source_hash OR rev_review->''decision'' IS DISTINCT FROM orig_review->''decision''\n     OR orig_review->>''decision'' NOT IN(''0'',''1'') OR length(btrim(COALESCE(orig_review->>''reason'','''')))=0 OR length(btrim(COALESCE(orig_review->>''evidence_ref'','''')))=0\n     OR length(btrim(COALESCE(rev_review->>''reason'','''')))=0 OR length(btrim(COALESCE(rev_review->>''evidence_ref'','''')))=0\n     OR COALESCE(rev_review->>''reversal_reason'','''') NOT IN(''return'',''contract_cancellation'',''price_adjustment'',''original_correction'') OR vat_followup_date(rev_review->>''tax_date'') IS DISTINCT FROM true\n     OR abs((cr->>''amount_total'')::numeric)<>abs((cr->>''supply_amount'')::numeric)+abs((cr->>''tax_amount'')::numeric)+abs(COALESCE((cr->>''service_charge'')::numeric,0))\n     OR reversal_merchant IS NOT NULL AND (reversal_merchant->>''status''=''review_required'' OR reversal_merchant->>''effectiveCorpNum'' IS DISTINCT FROM cr->>''store_corp_num'')\n    THEN issues:=issues||finance_document_issue(''cancellation_unresolved'',''원승인·취소 관계와 현재 검토 지문을 확인하세요.'');END IF;\n   END LOOP;\n   FOR x IN SELECT to_jsonb(v) FROM unnest(ARRAY[''amount_total'',''supply_amount'',''tax_amount'',''service_charge'']) v LOOP\n    EXECUTE format(''SELECT COALESCE(sum(abs(t.%I)),0) FROM card_transactions t JOIN card_tax_reviews r USING(card_txn_id) WHERE r.original_card_txn_id=$1 AND COALESCE(t.excluded,0)=0 AND btrim(t.approval_type) IN(''''취소'''',''''부분취소'''',''''환불'''')'',x#>>''{}'') INTO n USING c->>''card_txn_id'';\n    IF n>abs(COALESCE((c->>(x#>>''{}''))::numeric,0)) THEN issues:=issues||finance_document_issue(''cancellation_exceeds_original'',''연결된 취소 성분 합계가 원승인을 넘습니다.'');END IF;\n   END LOOP;\n  ELSE\n   IF COALESCE(x->>''modifyCode'','''')<>'''' OR x->>''originalInvoiceId'' IS NOT NULL OR COALESCE(x->>''originalApprovalNumber'','''')<>'''' OR COALESCE(x->>''originalNtsSendKey'','''')<>'''' THEN issues:=issues||finance_document_issue(''correction_lineage_unresolved'',''수정 문서는 정확 계보 검토가 필요합니다.'');END IF;\n  END IF;\n END LOOP;\n RETURN jsonb_build_object(''issues'',issues,''times'',times,''summary'',p_ref||finance_document_summary(o.preview_json->''observation''),''counterparty'',counterparty,''candidateHash'',candidate->>''previewHash'',''snapshot'',candidate->''_safeSnapshot'',''reversals'',reversals,''merchant'',merchant);\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_draft jsonb, p_ref jsonb","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"s","argumentTypes":"jsonb, jsonb","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_same_time","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\nDECLARE raw_value text; stored_value text; digits text; projected text; sufficient boolean:=false; matches boolean; valid_projected boolean:=false; valid_stored boolean:=false;\nBEGIN\n IF p_stored IS NOT NULL AND length(p_stored)<=80 AND p_stored ~ ''^[0-9TZ +:.\\-]+$'' THEN stored_value:=p_stored;END IF;\n IF jsonb_typeof(p_raw)=''string'' AND length(p_raw#>>''{}'')<=80 AND (p_raw#>>''{}'') ~ ''^[0-9TZ +:.\\-]+$'' THEN raw_value:=p_raw#>>''{}'';digits:=regexp_replace(raw_value,''[^0-9]'','''',''g'');\n  IF length(digits)>=14 THEN projected:=substr(digits,1,4)||''-''||substr(digits,5,2)||''-''||substr(digits,7,2)||'' ''||substr(digits,9,2)||'':''||substr(digits,11,2)||'':''||substr(digits,13,2);\n  ELSIF length(digits)>=8 THEN projected:=substr(digits,1,4)||''-''||substr(digits,5,2)||''-''||substr(digits,7,2);END IF;\n END IF;\n IF projected IS NOT NULL AND stored_value IS NOT NULL THEN matches:=projected=stored_value;END IF;\n IF projected ~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}$'' THEN\n  valid_projected:=vat_followup_date(left(projected,10)) AND substr(projected,12,2)::integer<24 AND substr(projected,15,2)::integer<60 AND substr(projected,18,2)::integer<60;\n END IF;\n IF stored_value ~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}$'' THEN\n  valid_stored:=vat_followup_date(left(stored_value,10)) AND substr(stored_value,12,2)::integer<24 AND substr(stored_value,15,2)::integer<60 AND substr(stored_value,18,2)::integer<60;\n END IF;\n sufficient:=COALESCE((raw_value ~ ''^[0-9]{14}$'' OR raw_value ~ ''^[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}$'') AND valid_projected AND valid_stored,false);\n RETURN jsonb_build_object(''sourceId'',p_source,''version'',''card-approval-time-evidence-v1'',''rawValue'',raw_value,''projectedValue'',projected,''storedValue'',stored_value,\n ''projectionMatches'',matches,''evidenceSufficient'',sufficient,''status'',CASE WHEN NOT sufficient THEN ''unavailable'' WHEN matches THEN ''matched'' ELSE ''conflict'' END);\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_source text, p_raw jsonb, p_stored text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"i","argumentTypes":"text, jsonb, text","securityDefiner":false},{"cost":"100","kind":"f","name":"finance_same_write","rows":"0","binary":null,"config":null,"result":"jsonb","source":"\nDECLARE q finance_same_requests%ROWTYPE; prev finance_same_revisions%ROWTYPE; c finance_same_cases%ROWTYPE; p jsonb; input_value jsonb; basis jsonb; cas text; rev text; ver integer; result jsonb; why text;\nBEGIN\n PERFORM finance_same_lock();PERFORM finance_assert_same_definitions(current_schema());\n IF p_action NOT IN(''verify'',''withdraw'') OR finance_supply_id(to_jsonb(p_request)) IS DISTINCT FROM true OR finance_supply_id(to_jsonb(p_actor)) IS DISTINCT FROM true OR p_input->>''requestId'' IS DISTINCT FROM p_request THEN RAISE EXCEPTION ''Invalid same relation request'' USING ERRCODE=''22023'';END IF;\n SELECT * INTO q FROM finance_same_requests WHERE request_id=p_request;\n IF FOUND THEN\n  IF q.action<>p_action OR q.actor_user_id<>p_actor OR q.payload_json IS DISTINCT FROM p_input THEN RAISE EXCEPTION ''Same request conflict'' USING ERRCODE=''23514'';END IF;\n  PERFORM finance_same_assert_request(p_request);RETURN q.result_json||''{\"replayed\":true}''::jsonb;\n END IF;\n IF p_action=''verify'' THEN\n  IF finance_same_input(p_input,true) IS DISTINCT FROM true THEN RAISE EXCEPTION ''Invalid same relation verify'' USING ERRCODE=''22023'';END IF;\n  input_value:=p_input-ARRAY[''expectedPreviewHash'',''requestId''];p:=finance_same_candidate(input_value);basis:=p->''_basis'';p:=p-''_basis'';\n  IF p->>''canVerify''<>''true'' OR p->>''previewHash'' IS DISTINCT FROM p_input->>''expectedPreviewHash'' THEN RAISE EXCEPTION ''Same relation preview stale'' USING ERRCODE=''23514'';END IF;\n  cas:=p_input->>''caseId'';ver:=(p_input->>''expectedVersion'')::integer+1;\n  IF cas IS NULL THEN cas:=''same-''||finance_document_hash(jsonb_build_array(p_input#>>''{draft,subjectId}'',finance_same_pair(p_input->''draft'')));INSERT INTO finance_same_cases(case_id,subject_id,pair_key,created_request_id,actor_user_id) VALUES(cas,p_input#>>''{draft,subjectId}'',finance_same_pair(p_input->''draft''),p_request,p_actor);END IF;\n ELSE\n  SELECT * INTO c FROM finance_same_cases WHERE case_id=p_input->>''caseId'';SELECT * INTO prev FROM finance_same_revisions WHERE case_id=c.case_id ORDER BY version DESC LIMIT 1;\n  IF c.subject_id IS DISTINCT FROM p_input->>''subjectId'' OR prev.state IS DISTINCT FROM ''verified_same'' OR prev.version IS DISTINCT FROM (p_input->>''expectedVersion'')::integer OR prev.revision_id IS DISTINCT FROM p_input->>''expectedRevisionId'' OR length(btrim(p_input->>''reason'')) NOT BETWEEN 1 AND 2000 OR p_input->>''reason'' IS NULL\n   OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(p_input) key) IS DISTINCT FROM ARRAY[''caseId'',''expectedRevisionId'',''expectedVersion'',''reason'',''requestId'',''subjectId''] THEN RAISE EXCEPTION ''Same relation withdrawal stale'' USING ERRCODE=''23514'';END IF;\n  cas:=c.case_id;ver:=prev.version+1;input_value:=prev.input_json;p:=prev.preview_json;basis:=prev.basis_json;why:=p_input->>''reason'';\n END IF;\n rev:=''samev-''||finance_document_hash(jsonb_build_array(p_request,p_actor));\n INSERT INTO finance_same_revisions(revision_id,case_id,version,previous_revision_id,schema_version,state,input_json,preview_json,basis_json,proof_hash,withdrawal_reason,request_id,actor_user_id)\n VALUES(rev,cas,ver,CASE WHEN ver=1 THEN NULL ELSE p_input->>''expectedRevisionId'' END,''de1b-whole-revision-v1'',CASE p_action WHEN ''verify'' THEN ''verified_same'' ELSE ''withdrawn'' END,input_value,p,basis,finance_document_hash(jsonb_build_object(''input'',input_value,''preview'',p,''basis'',basis)),why,p_request,p_actor);\n result:=jsonb_build_object(''caseId'',cas,''revisionId'',rev,''version'',ver,''state'',CASE p_action WHEN ''verify'' THEN ''verified_same'' ELSE ''withdrawn'' END,''replayed'',false,''financialUseSupported'',false);\n INSERT INTO finance_same_requests(request_id,action,actor_user_id,payload_json,payload_hash,result_json) VALUES(p_request,p_action,p_actor,p_input,finance_document_hash(p_input),result);RETURN result;\nEND ","strict":false,"support":"0","language":"plpgsql","parallel":"u","variadic":"0","arguments":"p_action text, p_input jsonb, p_request text, p_actor text","leakProof":false,"parsedBody":null,"returnsSet":false,"transforms":null,"volatility":"v","argumentTypes":"text, jsonb, text, text","securityDefiner":false}],"tables":["finance_same_cases","finance_same_requests","finance_same_revisions"],"strictRelations":["finance_same_cases","finance_same_requests","finance_same_revisions"],"installation":{"relations":[{"kind":"r","name":"finance_same_cases","policies":[],"rowSecurit